    @Column(name = "split_from")
    private String splitFrom;

    /** The user who has the claim's editor open, locking it for every other user; null when no one
     *  has. */
    @Column(name = "edit_locked_by")
    private String editLockedBy;

    /** The last day (the sheet's today then) a reminder was written for the claim; null when never. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** The user a steward assigned the claim to while it was in review; null when never assigned. */
    @Column(name = "review_assignee")
    private String reviewAssignee;

    /** Whether a reminder has escalated the claim; a claim is escalated once ever. */
    @Column(name = "escalated", nullable = false)
    private boolean escalated;

    /** Whether a steward waived the claim's late charge: it bears none from then on. */
    @Column(name = "waived", nullable = false)
    private boolean waived;

    /** Whether the claim is held. A held claim still counts in every total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** The claim's external reference; null when it has none. No two claims of a sheet share one,
     *  comparing without regard to case. */
    @Column(name = "ref")
    private String ref;

    /** The claim's tags, sorted and comma separated (see {@link Tags}); null when it has none. */
    @Column(name = "tags")
    private String tags;

    /** The reason from the sheet's list the claim was voided with; null when none was given. */
    @Column(name = "void_reason")
    private String voidReason;

    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The claim's place in the order claims are added and forward-only rates saved (see
     *  {@link net.officefloor.hq.app.rate.Rate#appliesTo}): taken when it is added, kept when it is
