210	    /** Close the period, fixing each person's due-total and carried figure for it at what they are
211	     *  now, each pool member's cut for it at what it is now, and its own due-total at the sum of the
212	     *  due-totals. */
213	    public void close(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
214	            Map<String, BigDecimal> poolCuts) {
215	        this.closed = true;
216	        this.softClosed = false;
217	        fix(personTotals, personCarried, poolCuts);
218	    }
219	
220	    /** Soft-close the period, fixing its due-totals as {@link #close} does while leaving claims dated
221	     *  inside it open to change. */
222	    public void softClose(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
223	            Map<String, BigDecimal> poolCuts) {
224	        this.softClosed = true;
225	        fix(personTotals, personCarried, poolCuts);
226	    }
227	
228	    private void fix(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
229	            Map<String, BigDecimal> poolCuts) {
230	        this.poolCuts.clear();
231	        this.poolCuts.putAll(poolCuts);
232	        this.personTotals.clear();
233	        this.personTotals.putAll(personTotals);
234	        this.personCarried.clear();
235	        this.personCarried.putAll(personCarried);
236	        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
237	    }
238	
239	    /** Fold one person's fixed due-total, carried figure and opening balance for the period into another's (the one
240	     *  was merged into the other); the period's own due-total stays as it is. */
241	    public void mergePersonTotal(Long fromId, Long intoId) {
242	        BigDecimal from = personTotals.remove(fromId);
243	        if (from != null) {
244	            personTotals.merge(intoId, from, BigDecimal::add);
245	        }
246	        BigDecimal carried = personCarried.remove(fromId);
247	        if (carried != null) {
248	            personCarried.merge(intoId, carried, BigDecimal::add);
249	        }
250	        BigDecimal opening = personOpenings.remove(fromId);
251	        if (opening != null) {
252	            personOpenings.merge(intoId, opening, BigDecimal::add);
253	        }
254	    }
255	
256	    /** Drop one person's fixed due-total, carried figure and opening balance for the period (they left the sheet);
257	     *  the period's own due-total stays as it is. */
258	    public void dropPersonTotal(Long personId) {
259	        personTotals.remove(personId);
260	        personCarried.remove(personId);
261	        personOpenings.remove(personId);
262	    }
263	
264	    /** Reopen the period: its due-totals and carried figures are live again. */
265	    public void reopen() {
266	        this.closed = false;
267	        this.softClosed = false;
268	        this.closedTotal = null;
269	        this.personTotals.clear();
270	        this.personCarried.clear();
271	        this.poolCuts.clear();
272	    }
273	}
