68	    /** Add a period, capping each person's open or pending claims in it when a cap is given (null:
69	     *  none); refused when its to-date is before its from-date, its cap is below 1, its name is in use
70	     *  on the sheet, or it shares a day with another period. */
71	    @Transactional
72	    public synchronized Period add(String sheetId, String user, String name, LocalDate from, LocalDate to,
73	            Integer cap) {
74	        sheets.load(sheetId, user);
75	        if (cap != null && cap < 1) {
76	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's claim cap must be at least 1");
77	        }
78	        if (to.isBefore(from)) {
79	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
80	        }
81	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
82	            throw nameInUse();
83	        }
84	        if (periods.overlaps(sheetId, from, to)) {
85	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
86	        }
87	        Period saved;
88	        try {
89	            saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
90	        } catch (DataIntegrityViolationException e) {
91	            throw nameInUse();
92	        }
93	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
94	                + " from=" + saved.getFromDate() + " to=" + saved.getToDate()
95	                + (saved.getClaimCap() == null ? "" : " cap=" + saved.getClaimCap()));
96	        history.record(sheetId);
97	        return saved;
98	    }
