100	    /** Generate one period per calendar month from the from-date's month to the to-date's month
101	     *  (the from-date the sheet's today when none is given), each running from the first to the last
102	     *  day of its month and named yyyy-mm; a month whose name is in use on the sheet, or whose days
103	     *  overlap a period on it, is left out. Refused when the to-date is before the from-date. A
104	     *  viewer's generate makes none. */
105	    @Transactional
106	    public synchronized List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
107	        sheets.load(sheetId, user);
108	        if (from == null) {
109	            from = sheets.today(sheetId);
110	        }
111	        if (to.isBefore(from)) {
112	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date");
113	        }
114	        if (SheetRole.VIEWER.equals(roles.roleOf(sheetId, user))) {
115	            return List.of();
116	        }
117	        List<Period> made = new ArrayList<>();
118	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
119	            String name = month.toString();
120	            LocalDate first = month.atDay(1);
121	            LocalDate last = month.atEndOfMonth();
122	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
123	                continue;
124	            }
125	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
126	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
127	                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
128	            made.add(saved);
129	        }
130	        history.record(sheetId);
131	        return made;
132	    }
