134	    /** Generate the twelve monthly periods of the fiscal year named by the year, as {@link #generate}
135	     *  does, from the first day of the sheet's fiscal year start month in that year. */
136	    @Transactional
137	    public synchronized List<Period> generateFiscalYear(String sheetId, String user, int year) {
138	        LocalDate first = LocalDate.of(year, sheets.fiscalStartMonth(sheetId), 1);
139	        return generate(sheetId, user, first, first.plusMonths(12).minusDays(1));
140	    }
