142	    /** What a rollover came to: the periods it generated, and every period it changed (those made
143	     *  and the new year's first period, whose openings it added to). */
144	    public record RolledOver(List<Period> made, List<Period> changed) {
145	    }
146	
147	    /** Roll the fiscal year named by the year over: generate the next fiscal year's twelve periods as
148	     *  {@link #generateFiscalYear} does, then add each person's open figure at the end of the old
149	     *  year's last period to their opening balance for the new year's first period. A person's open
150	     *  figure is the due of their claims that count, whose due-by falls in a period of the old year,
151	     *  and that were OPEN or PENDING at that last period's end; what an earlier rollover of the same
152	     *  year, not undone, added there is taken off it. Every period of the old year still open is then
153	     *  soft-closed, earliest first, as {@link #softClose} would. The rollover is kept so it can be undone
154	     *  ({@link #undoRollover}). Refused unless the user acts as a steward, or when the old year has
155	     *  no periods. */
156	    @Transactional
157	    public synchronized RolledOver rollover(String sheetId, String user, int year) {
158	        sheets.load(sheetId, user);
159	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
160	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may roll a year over");
161	        }
162	        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId);
163	        String oldFy = "FY" + year;
164	        List<Period> oldYear = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
165	                .filter(p -> fiscalYear(p.getFromDate(), fiscalStartMonth).equals(oldFy)).toList();
166	        if (oldYear.isEmpty()) {
167	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "That fiscal year has no periods");
168	        }
169	        LocalDate end = oldYear.stream().map(Period::getToDate).max(LocalDate::compareTo).orElseThrow();
170	        List<Period> made = generateFiscalYear(sheetId, user, year + 1);
171	        String newFy = "FY" + (year + 1);
172	        Period first = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
173	                .filter(p -> fiscalYear(p.getFromDate(), fiscalStartMonth).equals(newFy)).findFirst()
174	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
175	                        "The next fiscal year has no first period"));
176	        List<Person> onSheet = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
177	        Map<Long, BigDecimal> open = new HashMap<>();
178	        LocalDate today = sheets.today(sheetId);
179	        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
180	            Person person = onSheet.stream().filter(p -> p.getId().equals(c.getPersonId())).findFirst().orElse(null);
181	            boolean inOldYear = oldYear.stream().anyMatch(p -> !c.getDueBy().isBefore(p.getFromDate())
182	                    && !c.getDueBy().isAfter(p.getToDate()));
183	            if (person == null || !inOldYear || !Dues.countsAsOf(person, c, end, today)) {
184	                continue;
185	            }
186	            ClaimStatus then = c.statusOn(end);
187	            if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
188	                continue;
189	            }
190	            BigDecimal figure = dues.figure(sheetId, person, c);
191	            if (figure != null) {
192	                open.merge(person.getId(), figure, BigDecimal::add);
193	            }
194	        }
195	        Period locked = periods.lockByIdAndSheetId(first.getId(), sheetId)
196	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
197	        // what an earlier rollover of the year, not undone, already set there is not set again
198	        Map<Long, BigDecimal> already = new HashMap<>();
199	        for (Rollover earlier : rollovers.findBySheetIdAndFyAndUndoneFalse(sheetId, oldFy)) {
200	            if (earlier.getOpeningPeriodId().equals(locked.getId())) {
201	                earlier.getOpenings().forEach((personId, amount) -> already.merge(personId, amount, BigDecimal::add));
202	            }
203	        }
204	        Map<Long, BigDecimal> openings = new HashMap<>();
205	        for (Person person : onSheet) {
206	            BigDecimal amount = open.getOrDefault(person.getId(), BigDecimal.ZERO)
207	                    .subtract(already.getOrDefault(person.getId(), BigDecimal.ZERO));
208	            if (amount.signum() == 0) {
209	                continue;
210	            }
211	            amount = amount.setScale(2);
212	            locked.addOpening(person.getId(), amount);
213	            openings.put(person.getId(), amount);
214	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + person.getName()
215	                    + " period=" + locked.getName() + " amount=" + amount.toPlainString());
216	        }
217	        Period saved = periods.saveAndFlush(locked);
218	        rollovers.save(new Rollover(sheetId, user, today, oldFy, saved.getId(),
219	                made.stream().map(Period::getId).collect(Collectors.toSet()), openings));
220	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user + " fy=" + oldFy + " periods=" + made.size());
221	        history.record(sheetId);
222	        List<Period> changed = new ArrayList<>(made.stream().filter(p -> !p.getId().equals(saved.getId())).toList());
223	        changed.add(saved);
224	        // every period of the old year still open is soft-closed, earliest first
225	        for (Period old : oldYear) {
226	            Period period = periods.lockByIdAndSheetId(old.getId(), sheetId).orElse(null);
227	            if (period != null && !period.isClosed() && !period.isSoftClosed()) {
228	                changed.add(softCloseOpen(sheetId, user, period));
229	            }
230	        }
231	        return new RolledOver(made, changed);
232	    }
