234	    /** What undoing a rollover came to: the ids of the periods it removed, and the period whose
235	     *  opening balances it took back (null when that period was one it removed). */
236	    public record RolloverUndone(List<Long> removed, Period changed) {
237	    }
238	
239	    /** Undo the last rollover made on the sheet: remove the periods it generated and take back the
240	     *  opening balances it set. Refused unless the user is a steward and the one who made it, on the
241	     *  sheet-today it was made, it is not already undone, and no claim on the sheet now belongs to
242	     *  (is due by a day inside) a period it generated. */
243	    @Transactional
244	    public synchronized RolloverUndone undoRollover(String sheetId, String user) {
245	        sheets.load(sheetId, user);
246	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
247	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may undo a rollover");
248	        }
249	        Rollover last = rollovers.findFirstBySheetIdOrderByIdDesc(sheetId)
250	                .filter(r -> !r.isUndone())
251	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no rollover to undo"));
252	        if (!last.getMadeBy().equals(user)) {
253	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who made the rollover may undo it");
254	        }
255	        if (!last.getMadeOn().equals(sheets.today(sheetId))) {
256	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rollover can only be undone on the day it was made");
257	        }
258	        List<Period> generated = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
259	                .filter(p -> last.getPeriodIds().contains(p.getId())).toList();
260	        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
261	            boolean inGenerated = generated.stream().anyMatch(p -> !c.getDueBy().isBefore(p.getFromDate())
262	                    && !c.getDueBy().isAfter(p.getToDate()));
263	            if (inGenerated) {
264	                throw new ResponseStatusException(HttpStatus.CONFLICT,
265	                        "A claim now belongs to a period the rollover generated");
266	            }
267	        }
268	        Period changed = null;
269	        if (!last.getPeriodIds().contains(last.getOpeningPeriodId())) {
270	            Period first = periods.lockByIdAndSheetId(last.getOpeningPeriodId(), sheetId).orElse(null);
271	            if (first != null) {
272	                last.getOpenings().forEach((personId, amount) -> first.addOpening(personId, amount.negate()));
273	                first.dropZeroOpenings();
274	                changed = periods.saveAndFlush(first);
275	            }
276	        }
277	        periods.deleteAll(generated);
278	        periods.flush();
279	        last.undo();
280	        rollovers.save(last);
281	        audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user + " fy=" + last.getFy());
282	        history.record(sheetId);
283	        return new RolloverUndone(generated.stream().map(Period::getId).toList(), changed);
284	    }
