286	    /** Generate the four calendar quarters of the year, each running from the first day of its
287	     *  first month to the last day of its third month and named yyyy-Qn; a quarter whose name is in
288	     *  use on the sheet, or whose days overlap a period on it, is left out. */
289	    @Transactional
290	    public synchronized List<Period> generateQuarters(String sheetId, String user, int year) {
291	        sheets.load(sheetId, user);
292	        List<Period> made = new ArrayList<>();
293	        for (int quarter = 1; quarter <= 4; quarter++) {
294	            String name = year + "-Q" + quarter;
295	            LocalDate first = LocalDate.of(year, quarter * 3 - 2, 1);
296	            LocalDate last = YearMonth.of(year, quarter * 3).atEndOfMonth();
297	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
298	                continue;
299	            }
300	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
301	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
302	                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
303	            made.add(saved);
304	        }
305	        history.record(sheetId);
306	        return made;
307	    }
