309	    /** The fiscal year a day falls in (FYyyyy), with fiscal years starting on the first day of the
310	     *  month: named by the calendar year that first day falls in. */
311	    public static String fiscalYear(LocalDate day, int fiscalStartMonth) {
312	        return "FY" + (day.getMonthValue() >= fiscalStartMonth ? day.getYear() : day.getYear() - 1);
313	    }
