315	    /** Close a period (an open or a soft-closed one), fixing its due-total at what it is now; refused when the permission matrix does
316	     *  not allow the user's role to close, or it is already closed. */
317	    @Transactional
318	    public Period close(String sheetId, String user, long periodId) {
319	        sheets.load(sheetId, user);
320	        if (!roles.may(sheetId, user, "close")) {
321	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
322	        }
323	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
324	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
325	        if (period.isClosed()) {
326	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
327	        }
328	        return closeOpen(sheetId, user, period, "");
329	    }
