331	    /** Soft-close a period, fixing its due-total and each person's for it at what they are now while
332	     *  claims dated inside it stay open to change; refused when the permission matrix does not allow
333	     *  the user's role to close, or it is already closed or soft-closed. */
334	    @Transactional
335	    public Period softClose(String sheetId, String user, long periodId) {
336	        sheets.load(sheetId, user);
337	        if (!roles.may(sheetId, user, "close")) {
338	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
339	        }
340	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
341	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
342	        if (period.isClosed() || period.isSoftClosed()) {
343	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
344	        }
345	        return softCloseOpen(sheetId, user, period);
346	    }
