348	    /** Soft-close an open period, fixing its due-total and each person's for it at what they are now. */
349	    private Period softCloseOpen(String sheetId, String user, Period period) {
350	        period.softClose(personTotals(sheetId, period), personCarried(sheetId, period),
351	                pools.currentCuts(sheetId));
352	        Period saved = periods.saveAndFlush(period);
353	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
354	                + " total=" + saved.getClosedTotal().toPlainString());
355	        history.record(sheetId);
356	        return saved;
357	    }
