359	    /** Close every open period on the sheet whose to-date plus the grace days is before the day,
360	     *  earliest to-date first, each as a close by hand would, its record marked auto=yes. */
361	    @Transactional(propagation = Propagation.MANDATORY)
362	    public void autoClose(String sheetId, String user, int graceDays, LocalDate day) {
363	        for (Period period : periods.findOpenEndingBefore(sheetId, day.minusDays(graceDays))) {
364	            closeOpen(sheetId, user, period, " auto=yes");
365	        }
366	    }
367	
368	    /** Close an open period, fixing its due-total at what it is now; the suffix ends its record. */
369	    private Period closeOpen(String sheetId, String user, Period period, String suffix) {
370	        period.close(personTotals(sheetId, period), personCarried(sheetId, period),
371	                pools.currentCuts(sheetId));
372	        Period saved = periods.saveAndFlush(period);
373	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
374	                + " total=" + saved.getClosedTotal().toPlainString() + suffix);
375	        history.record(sheetId);
376	        return saved;
377	    }
378	
379	    /** Reopen a closed or soft-closed period, making its due-total live again; refused when the permission matrix
380	     *  does not allow the user's role to reopen, the period is not closed, or it is locked. */
381	    @Transactional
382	    public Period reopen(String sheetId, String user, long periodId) {
383	        sheets.load(sheetId, user);
384	        if (!roles.may(sheetId, user, "reopen")) {
385	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
386	        }
387	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
388	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
389	        if (!period.isClosed() && !period.isSoftClosed()) {
390	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
391	        }
392	        if (period.isLocked()) {
393	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is locked");
394	        }
395	        period.reopen();
396	        Period saved = periods.saveAndFlush(period);
397	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
398	        history.record(sheetId);
399	        return saved;
400	    }
401	
402	    /** Lock or unlock a period; refused unless the user acts as a steward, or when it is already
403	     *  locked (or, to unlock, not locked). */
404	    @Transactional
405	    public Period lock(String sheetId, String user, long periodId, boolean lock) {
406	        sheets.load(sheetId, user);
407	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
408	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
409	                    "Only a steward may " + (lock ? "lock" : "unlock") + " a period");
410	        }
411	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
412	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
413	        if (period.isLocked() == lock) {
414	            throw new ResponseStatusException(HttpStatus.CONFLICT,
415	                    lock ? "That period is already locked" : "That period is not locked");
416	        }
417	        period.setLocked(lock);
418	        Period saved = periods.saveAndFlush(period);
419	        audit.recordOnCommit((lock ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
420	                + " period=" + saved.getName());
421	        history.record(sheetId);
422	        return saved;
423	    }
424	
425	    /** Each person's due-total for a period, by the person's id: the due figures of their claims
426	     *  whose due-by falls in it and that count by their status at its end, skipping those with no due
427	     *  and those the live rules leave out (see Dues#countsAsOf). */
428	    private Map<Long, BigDecimal> personTotals(String sheetId, Period period) {
429	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
430	                .collect(Collectors.toMap(Person::getId, Function.identity()));
431	        Map<Long, BigDecimal> totals = new HashMap<>();
432	        for (Long id : byId.keySet()) {
433	            totals.put(id, BigDecimal.ZERO.setScale(2));
434	        }
435	        LocalDate today = sheets.today(sheetId);
436	        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
437	            Person person = byId.get(c.getPersonId());
438	            if (person == null || !Dues.countsAsOf(person, c, period.getToDate(), today) || c.getDueBy().isBefore(period.getFromDate())
439	                    || c.getDueBy().isAfter(period.getToDate())) {
440	                continue;
441	            }
442	            BigDecimal figure = dues.figure(sheetId, person, c);
443	            if (figure != null) {
444	                totals.merge(person.getId(), figure, BigDecimal::add);
445	            }
446	        }
447	        return totals;
448	    }
449	
450	    /** Each person's carried figure for a period, by the person's id: their opening balance for it
451	     *  plus the due figures of their claims that count by their status at its end whose due-by falls
452	     *  in a period ending before it starts and that were still open (or pending) at its end, skipping
453	     *  those with no due. */
454	    private Map<Long, BigDecimal> personCarried(String sheetId, Period period) {
455	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
456	                .collect(Collectors.toMap(Person::getId, Function.identity()));
457	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
458	        Map<Long, BigDecimal> carried = new HashMap<>();
459	        for (Long id : byId.keySet()) {
460	            carried.put(id, period.getPersonOpenings().getOrDefault(id, BigDecimal.ZERO).setScale(2));
461	        }
462	        LocalDate today = sheets.today(sheetId);
463	        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
464	            Person person = byId.get(c.getPersonId());
465	            boolean earlier = all.stream().anyMatch(p -> !c.getDueBy().isBefore(p.getFromDate())
466	                    && !c.getDueBy().isAfter(p.getToDate()) && p.getToDate().isBefore(period.getFromDate()));
467	            if (person == null || !earlier || !Dues.countsAsOf(person, c, period.getToDate(), today)) {
468	                continue;
469	            }
470	            ClaimStatus then = c.statusOn(period.getToDate());
471	            if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
472	                continue;
473	            }
474	            BigDecimal figure = dues.figure(sheetId, person, c);
475	            if (figure != null) {
476	                carried.merge(person.getId(), figure, BigDecimal::add);
477	            }
478	        }
479	        return carried;
480	    }
481	
482	    private static ResponseStatusException nameInUse() {
483	        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
484	    }
485	}
