2	
3	import jakarta.persistence.Column;
4	import jakarta.persistence.Entity;
5	import jakarta.persistence.GeneratedValue;
6	import jakarta.persistence.GenerationType;
7	import jakarta.persistence.Id;
8	import jakarta.persistence.Table;
9	import java.math.BigDecimal;
10	import java.time.LocalDate;
11	import java.util.Arrays;
12	import java.util.Map;
13	import java.util.Objects;
14	import java.util.TreeMap;
15	import java.util.stream.Collectors;
16	
17	/** A revision of a period in its sheet's history: its days, whether it was closed or soft-closed,
18	 *  and the due-totals fixed then, after a change, recorded on the sheet's today then. */
19	@Entity
20	@Table(name = "period_revision")
21	public class PeriodRevision {
22	
23	    @Id
24	    @GeneratedValue(strategy = GenerationType.IDENTITY)
25	    private Long id;
26	
27	    @Column(name = "sheet_id", nullable = false)
28	    private String sheetId;
29	
30	    @Column(name = "period_id", nullable = false)
31	    private Long periodId;
32	
33	    /** The sheet's today when the revision was recorded. */
34	    @Column(name = "recorded_on", nullable = false)
35	    private LocalDate recordedOn;
36	
37	    @Column(name = "name", nullable = false)
38	    private String name;
39	
40	    @Column(name = "from_date", nullable = false)
41	    private LocalDate fromDate;
42	
43	    @Column(name = "to_date", nullable = false)
44	    private LocalDate toDate;
45	
46	    @Column(name = "closed", nullable = false)
47	    private boolean closed;
48	
49	    @Column(name = "soft_closed", nullable = false)
50	    private boolean softClosed;
51	
52	    @Column(name = "locked", nullable = false)
53	    private boolean locked;
54	
55	    @Column(name = "closed_total", precision = 14, scale = 2)
56	    private BigDecimal closedTotal;
57	
58	    @Column(name = "claim_cap")
59	    private Integer claimCap;
60	
61	    /** Each person's fixed due-total, "person-id:total", separated by ";"; blank while open. */
62	    @Column(name = "person_totals", nullable = false)
63	    private String personTotals;
64	
65	    /** Each person's fixed carried figure, "person-id:carried", separated by ";"; blank while open. */
66	    @Column(name = "person_carried", nullable = false)
67	    private String personCarried;
68	
69	    /** Each person's opening balance, "person-id:opening", separated by ";". */
70	    @Column(name = "person_openings", nullable = false)
71	    private String personOpenings;
72	
73	    /** Each pool member's fixed cut, "pool-id:member-key=cut", separated by ";"; blank while open. */
74	    @Column(name = "pool_cuts", nullable = false)
75	    private String poolCuts;
76	
77	    protected PeriodRevision() {
78	    }
79	
80	    /** A revision of the period as it is now, recorded on the day. */
81	    public PeriodRevision(Period period, LocalDate recordedOn) {
82	        this.sheetId = period.getSheetId();
83	        this.periodId = period.getId();
84	        this.recordedOn = recordedOn;
85	        this.name = period.getName();
86	        this.fromDate = period.getFromDate();
87	        this.toDate = period.getToDate();
88	        this.closed = period.isClosed();
89	        this.softClosed = period.isSoftClosed();
90	        this.locked = period.isLocked();
91	        this.closedTotal = period.getClosedTotal();
92	        this.personTotals = totals(period.getPersonTotals());
93	        this.personCarried = totals(period.getPersonCarried());
94	        this.personOpenings = totals(period.getPersonOpenings());
95	        this.poolCuts = cuts(period.getPoolCuts());
96	        this.claimCap = period.getClaimCap();
97	    }
98	
99	    private static String totals(Map<Long, BigDecimal> totals) {
100	        return new TreeMap<>(totals).entrySet().stream()
101	                .map(e -> e.getKey() + ":" + e.getValue().setScale(2).toPlainString())
102	                .collect(Collectors.joining(";"));
103	    }
104	
105	    private static String cuts(Map<String, BigDecimal> cuts) {
106	        return new TreeMap<>(cuts).entrySet().stream()
107	                .map(e -> e.getKey() + "=" + e.getValue().setScale(2).toPlainString())
108	                .collect(Collectors.joining(";"));
109	    }
110	
111	    private static Map<String, BigDecimal> parseCuts(String text) {
112	        Map<String, BigDecimal> cuts = new TreeMap<>();
113	        Arrays.stream(text.split(";")).filter(t -> !t.isBlank()).forEach(t -> {
114	            int at = t.lastIndexOf('=');
115	            cuts.put(t.substring(0, at), new BigDecimal(t.substring(at + 1)));
116	        });
117	        return cuts;
118	    }
119	
120	    /** Whether the period is now as this revision has it. */
121	    public boolean matches(Period period) {
122	        return Objects.equals(name, period.getName()) && Objects.equals(fromDate, period.getFromDate())
123	                && Objects.equals(toDate, period.getToDate()) && closed == period.isClosed()
124	                && softClosed == period.isSoftClosed() && locked == period.isLocked()
125	                && (closedTotal == null ? period.getClosedTotal() == null
126	                        : period.getClosedTotal() != null && closedTotal.compareTo(period.getClosedTotal()) == 0)
127	                && personTotals.equals(totals(period.getPersonTotals()))
128	                && personCarried.equals(totals(period.getPersonCarried()))
129	                && personOpenings.equals(totals(period.getPersonOpenings()))
130	                && poolCuts.equals(cuts(period.getPoolCuts()))
131	                && Objects.equals(claimCap, period.getClaimCap());
132	    }
133	
134	    /** The period as this revision has it, detached: for showing only, never saved. */
135	    public Period toPeriod() {
136	        return Period.revised(sheetId, periodId, name, fromDate, toDate, closed, softClosed, closedTotal,
137	                parse(personTotals), parse(personCarried), parse(personOpenings), claimCap, locked,
138	                parseCuts(poolCuts));
139	    }
140	
141	    private static Map<Long, BigDecimal> parse(String text) {
142	        Map<Long, BigDecimal> figures = new TreeMap<>();
143	        Arrays.stream(text.split(";")).filter(t -> !t.isBlank()).forEach(t -> {
144	            int at = t.indexOf(':');
145	            figures.put(Long.valueOf(t.substring(0, at)), new BigDecimal(t.substring(at + 1)));
146	        });
147	        return figures;
148	    }
149	
150	    public Long getPeriodId() {
151	        return periodId;
152	    }
153	
154	    public LocalDate getRecordedOn() {
155	        return recordedOn;
156	    }
157	}
