4	import java.util.ArrayList;
5	import java.util.LinkedHashMap;
6	import java.util.List;
7	import java.util.Map;
8	import java.util.regex.Pattern;
9	import net.officefloor.hq.app.Audit;
10	import net.officefloor.hq.app.history.History;
11	import net.officefloor.hq.app.person.Person;
12	import net.officefloor.hq.app.person.PersonRepository;
13	import net.officefloor.hq.app.sheet.SheetService;
14	import org.springframework.http.HttpStatus;
15	import org.springframework.stereotype.Service;
16	import org.springframework.transaction.annotation.Transactional;
17	import org.springframework.web.server.ResponseStatusException;
18	
19	/** The opening balances box: lines of name,period,amount, each adding the amount to the named
20	 *  person's carried figure for the period (their opening balance for it). */
21	@Service
22	public class OpeningImportService {
23	
24	    /** An opening amount: 0.00 or more, with exactly two decimals. */
25	    private static final Pattern AMOUNT = Pattern.compile("\\s*\\d{1,12}\\.\\d{2}\\s*");
26	
27	    /** One parsed line: the person, the period and the amount. */
28	    private record Line(Person person, Period period, BigDecimal amount) {
29	    }
30	
31	    private final PersonRepository people;
32	    private final PeriodRepository periods;
33	    private final SheetService sheets;
34	    private final History history;
35	    private final Audit audit;
36	
37	    public OpeningImportService(PersonRepository people, PeriodRepository periods, SheetService sheets,
38	            History history, Audit audit) {
39	        this.people = people;
40	        this.periods = periods;
41	        this.sheets = sheets;
42	        this.history = history;
43	        this.audit = audit;
44	    }
45	
46	    /** What an import came to: how many lines went through, and the periods they changed. */
47	    public record Imported(int added, List<Period> periods) {
48	    }
49	
50	    /** Add each line's amount to its person's opening balance for its period, in order, checking
51	     *  every line first; one change, so when any line is refused nothing is changed and nothing is
52	     *  recorded. A person is named by name or alias and a period by name, without regard to case.
53	     *  Blank lines are skipped; an import with no lines is refused. */
54	    @Transactional
55	    public Imported importOpenings(String sheetId, String user, String text) {
56	        sheets.load(sheetId, user);
57	        List<Period> onSheet = periods.findBySheetIdOrderByFromDateAsc(sheetId);
58	        List<Line> lines = new ArrayList<>();
59	        int n = 0;
60	        for (String raw : text.split("\\R")) {
61	            n++;
62	            if (!raw.isBlank()) {
63	                lines.add(parse(sheetId, onSheet, n, raw));
64	            }
65	        }
66	        if (lines.isEmpty()) {
67	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
68	        }
69	        Map<Long, Period> changed = new LinkedHashMap<>();
70	        for (Line line : lines) {
71	            Period period = changed.computeIfAbsent(line.period().getId(), id -> periods.lockByIdAndSheetId(id, sheetId)
72	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet")));
73	            period.addOpening(line.person().getId(), line.amount());
74	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
75	                    + " period=" + period.getName() + " amount=" + line.amount().toPlainString());
76	        }
77	        List<Period> saved = periods.saveAllAndFlush(changed.values());
78	        history.record(sheetId);
79	        return new Imported(lines.size(), saved);
80	    }
81	
82	    /** A line of name,period,amount. */
83	    private Line parse(String sheetId, List<Period> onSheet, int n, String raw) {
84	        String[] fields = raw.split(",", -1);
85	        if (fields.length != 3) {
86	            throw refused(n, "expected name,period,amount");
87	        }
88	        String name = fields[0].trim();
89	        Person person = name.isEmpty() ? null : people.findByNameOrAlias(sheetId, name).orElse(null);
90	        if (person == null) {
91	            throw refused(n, "no one named \"" + name + "\" on this sheet");
92	        }
93	        String periodName = fields[1].trim();
94	        Period period = onSheet.stream().filter(p -> p.getName().equalsIgnoreCase(periodName)).findFirst()
95	                .orElseThrow(() -> refused(n, "no period named \"" + periodName + "\" on this sheet"));
96	        if (!AMOUNT.matcher(fields[2]).matches()) {
97	            throw refused(n, "the amount must be 0.00 or more, with two decimals");
98	        }
99	        return new Line(person, period, new BigDecimal(fields[2].trim()));
100	    }
101	
102	    private static ResponseStatusException refused(int n, String why) {
103	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": " + why);
104	    }
105	}
