12	public interface PeriodRepository extends JpaRepository<Period, Long> {
13	
14	    /** The periods on a sheet, earliest first. */
15	    List<Period> findBySheetIdOrderByFromDateAsc(String sheetId);
16	
17	    /** Whether the name is in use on the sheet, compared without regard to case. */
18	    boolean existsBySheetIdAndNameIgnoreCase(String sheetId, String name);
19	
20	    /** Whether a period on the sheet shares a day with the days from one date to another. */
21	    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.fromDate <= :to and p.toDate >= :from")
22	    boolean overlaps(String sheetId, LocalDate from, LocalDate to);
23	
24	    /** Whether the day falls inside a closed period on the sheet. */
25	    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.closed = true"
26	            + " and p.fromDate <= :day and p.toDate >= :day")
27	    boolean closedOn(String sheetId, LocalDate day);
28	
29	    /** Whether the day falls inside a soft-closed period on the sheet. */
30	    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.softClosed = true"
31	            + " and p.fromDate <= :day and p.toDate >= :day")
32	    boolean softClosedOn(String sheetId, LocalDate day);
33	
34	    /** The period on the sheet whose days contain the day, if any. */
35	    @Query("select p from Period p where p.sheetId = :sheetId and p.fromDate <= :day and p.toDate >= :day")
36	    Optional<Period> findOn(String sheetId, LocalDate day);
37	
38	    /** Move the period's last claim number on by one; the row stays locked until the transaction
39	     *  ends, so two claims opened in it at once get one number each. */
40	    @Modifying
41	    @Query("update Period p set p.lastClaimNumber = p.lastClaimNumber + 1 where p.id = :id")
42	    int advanceClaimNumber(Long id);
43	
44	    @Query("select p.lastClaimNumber from Period p where p.id = :id")
45	    int lastClaimNumber(Long id);
46	
47	    /** A period on a sheet, locked for the rest of the transaction so two closes or reopens of
48	     *  it happen one after the other. */
49	    @Lock(LockModeType.PESSIMISTIC_WRITE)
50	    @Query("select p from Period p where p.id = :id and p.sheetId = :sheetId")
51	    Optional<Period> lockByIdAndSheetId(Long id, String sheetId);
52	
53	    /** The open periods (neither closed nor soft-closed) on a sheet whose to-date is before the day, earliest to-date first. */
54	    @Query("select p from Period p where p.sheetId = :sheetId and p.closed = false and p.softClosed = false and p.toDate < :day"
