    31	    @Override
    32	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
    33	        if (HttpMethod.GET.matches(request.getMethod())) {
    34	            return true;
    35	        }
    36	        String user = request.getHeader("X-User");
    37	        @SuppressWarnings("unchecked")
    38	        Map<String, String> vars = (Map<String, String>) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
    39	        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
    40	        if (user != null && sheetId != null) {
    41	            String sheet = sheetId.trim();
    42	            String name = user.trim();
    43	            Supplier<String> actingFor = () -> roles.delegatorOf(sheet, name).orElse(null);
