12	/** A statement taken of a person: their due-total on the day it was taken as of, and how many of their
13	 *  claims counted then. */
14	@Entity
15	@Table(name = "statement")
16	public class Statement {
17	
18	    @Id
19	    @GeneratedValue(strategy = GenerationType.IDENTITY)
20	    private Long id;
21	
22	    @Column(name = "sheet_id", nullable = false)
23	    private String sheetId;
24	
25	    @Column(name = "person_id", nullable = false)
26	    private Long personId;
27	
28	    /** The sheet's today when the statement was taken. */
29	    @Column(name = "taken_on", nullable = false)
30	    private LocalDate takenOn;
31	
32	    @Column(name = "taken_by", nullable = false)
33	    private String takenBy;
34	
35	    /** The person's due-total then; null when it was n/a. */
36	    @Column(name = "due_total", precision = 14, scale = 2)
37	    private BigDecimal dueTotal;
38	
39	    @Column(name = "claims", nullable = false)
40	    private int claims;
41	
42	    /** The earlier day the statement was taken as of; null when it was taken as of the sheet's today. */
43	    @Column(name = "as_of")
44	    private LocalDate asOf;
45	
46	    /** The sheet's today when the statement was cancelled; null while it stands. */
47	    @Column(name = "cancelled_on")
48	    private LocalDate cancelledOn;
49	
50	    /** Whether the statement came to its person with a merge or a transfer (it was another person's). */
51	    @Column(name = "carried", nullable = false)
52	    private boolean carried;
53	
54	    protected Statement() {
55	    }
56	
57	    public Statement(String sheetId, Long personId, LocalDate takenOn, String takenBy, BigDecimal dueTotal,
58	            int claims, LocalDate asOf) {
59	        this.sheetId = sheetId;
60	        this.personId = personId;
61	        this.takenOn = takenOn;
62	        this.takenBy = takenBy;
63	        this.dueTotal = dueTotal;
64	        this.claims = claims;
65	        this.asOf = asOf;
66	    }
67	
68	    /** A copy of this statement carried to a person (on this sheet or another) with a merge or a
69	     *  transfer: taken, cancelled and as of the same days, by the same user, to the same figures. */
70	    public Statement carriedTo(String toSheetId, Long toPersonId) {
71	        Statement copy = new Statement(toSheetId, toPersonId, takenOn, takenBy, dueTotal, claims, asOf);
72	        copy.cancelledOn = cancelledOn;
73	        copy.carried = true;
74	        return copy;
75	    }
76	
77	    public boolean isCarried() {
78	        return carried;
79	    }
80	
81	    public Long getId() {
82	        return id;
83	    }
84	
85	    public String getSheetId() {
86	        return sheetId;
87	    }
88	
89	    public Long getPersonId() {
90	        return personId;
91	    }
92	
93	    public LocalDate getTakenOn() {
94	        return takenOn;
95	    }
96	
97	    public LocalDate getCancelledOn() {
98	        return cancelledOn;
99	    }
100	
101	    /** Cancel the statement on a day (the sheet's today). */
102	    public void cancel(LocalDate day) {
103	        this.cancelledOn = day;
104	    }
105	
106	    /** Whether the statement stood at the end of a day: taken on or before it and not cancelled by then. */
107	    public boolean stoodOn(LocalDate day) {
108	        return !takenOn.isAfter(day) && (cancelledOn == null || cancelledOn.isAfter(day));
109	    }
110	
111	    public LocalDate getAsOf() {
112	        return asOf;
113	    }
114	
115	    /** The statement's date: the day it was taken as of, or else the day it was taken. */
116	    public LocalDate getStatedOn() {
117	        return asOf != null ? asOf : takenOn;
118	    }
119	
120	    public String getTakenBy() {
121	        return takenBy;
122	    }
123	
124	    public BigDecimal getDueTotal() {
125	        return dueTotal;
126	    }
127	
128	    public int getClaims() {
129	        return claims;
130	    }
131	}
