2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.ArrayList;
6	import java.util.List;
7	import java.util.Map;
8	import java.util.stream.Collectors;
9	import net.officefloor.hq.app.Audit;
10	import net.officefloor.hq.app.claim.Claim;
11	import net.officefloor.hq.app.claim.ClaimRepository;
12	import net.officefloor.hq.app.claim.Dues;
13	import net.officefloor.hq.app.history.History;
14	import net.officefloor.hq.app.rollup.Rollup;
15	import net.officefloor.hq.app.person.Person;
16	import net.officefloor.hq.app.person.PersonRepository;
17	import net.officefloor.hq.app.pool.PoolService;
18	import net.officefloor.hq.app.role.RoleService;
19	import net.officefloor.hq.app.role.SheetRole;
20	import net.officefloor.hq.app.sheet.SheetService;
21	import org.springframework.http.HttpStatus;
22	import org.springframework.stereotype.Service;
23	import org.springframework.transaction.annotation.Transactional;
24	import org.springframework.web.server.ResponseStatusException;
25	
26	/** The statements taken of people on a sheet. */
27	@Service
28	public class StatementService {
29	
30	    /** A statement just taken: the person, what their statements now come to, and their claims
31	     *  (newest first) as the statement bound them. */
32	    public record Taken(Person person, StatementSummary summary, List<Claim> claims) {
33	    }
34	
35	    private final StatementRepository statements;
36	    private final PersonRepository people;
37	    private final ClaimRepository claims;
38	    private final Dues dues;
39	    private final SheetService sheets;
40	    private final Rollup rollup;
41	    private final RoleService roles;
42	    private final History history;
43	    private final Audit audit;
44	    private final PoolService pools;
45	
46	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
47	            Dues dues, SheetService sheets, Rollup rollup, RoleService roles, History history, Audit audit,
48	            PoolService pools) {
49	        this.pools = pools;
50	        this.history = history;
51	        this.statements = statements;
52	        this.people = people;
53	        this.claims = claims;
54	        this.dues = dues;
55	        this.sheets = sheets;
56	        this.rollup = rollup;
57	        this.roles = roles;
58	        this.audit = audit;
59	    }
60	
61	    /** What each person's statements on the sheet come to, by person id; a person with none is
62	     *  missing. */
63	    @Transactional(readOnly = true)
64	    public Map<Long, StatementSummary> summaries(String sheetId) {
65	        return statements.findBySheetIdAndCancelledOnIsNullOrderByIdAsc(sheetId).stream()
66	                .collect(Collectors.groupingBy(Statement::getPersonId,
67	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
68	    }
69	
70	    /** What each person's statements on the sheet came to at the end of a day: those taken while the
71	     *  sheet's today was on or before it and not cancelled by then, by person id; a person with none
72	     *  is missing. */
73	    @Transactional(readOnly = true)
74	    public Map<Long, StatementSummary> summaries(String sheetId, LocalDate day) {
75	        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
76	                .filter(s -> s.stoodOn(day))
77	                .collect(Collectors.groupingBy(Statement::getPersonId,
78	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
79	    }
80	
81	    /** What one person's statements come to. */
82	    @Transactional(readOnly = true)
83	    public StatementSummary summary(String sheetId, long personId) {
84	        return StatementSummary.of(statements.findBySheetIdAndPersonIdAndCancelledOnIsNullOrderByIdAsc(sheetId, personId));
85	    }
86	
87	    /** Take a statement of a person: record their due-total now and bind each of their claims that
88	     *  counts in the live totals to its due as shown now, late charge included (a figure an earlier
89	     *  statement bound stays as it is); any other
90	     *  claim (one that does not count, a deferred one, or an open unbound one dated within one of their
91	     *  holds) is unbound. */
92	    @Transactional
93	    public Taken take(String sheetId, String user, long personId) {
94	        return take(sheetId, user, personId, null);
95	    }
96	
97	    /** Take a statement of a person as of a day (null: the sheet's today) on or before the sheet's
98	     *  today: the sheet as it stood at the end of that day (see {@link History}) stands in for it as
99	     *  it is now, that day for its today. Their due-total then is recorded, and each claim of theirs
100	     *  that counted in the live totals then is bound to the due it showed then, late charge included; every other claim
101	     *  of theirs is unbound. Refused when the day is after the sheet's today, or when the person was
102	     *  not on the sheet yet then. */
103	    @Transactional
104	    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
105	        LocalDate today = sheets.today(sheetId);
106	        if (asOf != null && asOf.isAfter(today)) {
107	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
108	                    "A statement cannot be taken as of a day after the sheet's today");
109	        }
110	        Person person = people.lockByIdAndSheetId(personId, sheetId)
111	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
112	        History.SheetAsOf then = asOf == null ? null : history.asOf(sheetId, asOf);
113	        Person was = then == null ? person : then.person(personId)
114	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
115	                        "The person was not on the sheet yet on that day"));
116	        List<Claim> bound = rollup.tracking(sheetId, user, () -> {
117	            List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
118	            Dues.Basis basis = then == null ? dues.now(sheetId) : then.basis();
119	            List<Claim> counted = Dues.live(was, then == null ? theirs : then.claimsOf(personId), basis.today());
120	            // their parts of claims shared with them count, and the parts others hold of theirs do not
121	            Map<Long, Person> everyone = then != null ? then.people()
122	                    : people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
123	                            .collect(Collectors.toMap(Person::getId, p -> p));
124	            Map<Long, List<Claim>> byPerson = (then != null ? then.claims()
125	                    : claims.findBySheetIdOrderByListedDesc(sheetId)).stream()
126	                    .collect(Collectors.groupingBy(Claim::getPersonId));
127	            Map<Long, Person> holders = everyone;
128	            List<BigDecimal> held = new ArrayList<>();
129	            for (Person other : everyone.values()) {
130	                for (Claim claim : Dues.live(other, byPerson.getOrDefault(other.getId(), List.of()), basis.today())) {
131	                    if (!claim.getShares().isEmpty()) {
132	                        BigDecimal part = dues.parts(basis, claim, dues.figure(basis, other, claim), holders).get(personId);
133	                        if (part != null) {
134	                            held.add(part);
135	                        }
136	                    }
137	                }
138	            }
139	            BigDecimal dueTotal = dues.dueTotal(basis, was, counted, holders, held,
140	                    pools.cutTotals(sheetId, asOf).getOrDefault(personId, BigDecimal.ZERO.setScale(2)));
141	            Map<Long, Claim> countedById = counted.stream().collect(Collectors.toMap(Claim::getId, c -> c));
142	            for (Claim claim : theirs) {
143	                Claim figured = countedById.get(claim.getId());
144	                if (figured != null) {
145	                    claim.bind(true, dues.bindable(basis, was, figured), dues.bindsNa(basis, was, figured));
146	                } else {
147	                    claim.bind(false, null);
148	                }
149	            }
150	            claims.saveAllAndFlush(theirs);
151	            statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size(), asOf));
152	            audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
153	                    + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.setScale(2).toPlainString())
154	                    + " claims=" + counted.size() + (asOf != null ? " asof=" + asOf : ""));
155	            return theirs;
156	        });
157	        return new Taken(person, summary(sheetId, personId), bound);
158	    }
159	
160	    /** Cancel a person's last statement: only a steward may, and only when one was taken. The claims
161	     *  it bound become live again (a figure an earlier statement bound is not restored), and the
162	     *  statement before it, if any, becomes their last. The cancelled statement is kept, marked with
163	     *  the sheet's today, so the sheet as of an earlier day still shows it. Their last is their own
164	     *  last statement, or, having none, the last one carried to them by a merge or a transfer. */
165	    @Transactional
166	    public Taken cancelLast(String sheetId, String user, long personId) {
167	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
168	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
169	        }
170	        Person person = people.lockByIdAndSheetId(personId, sheetId)
171	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
172	        List<Statement> taken = statements.findBySheetIdAndPersonIdAndCancelledOnIsNullOrderByIdAsc(sheetId, personId);
173	        if (taken.isEmpty()) {
174	            throw new ResponseStatusException(HttpStatus.CONFLICT, "No statement has been taken of this person");
175	        }
176	        Statement last = StatementSummary.last(taken);
177	        List<Claim> unbound = rollup.tracking(sheetId, user, () -> {
178	            List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
179	            theirs.forEach(claim -> claim.bind(false, null));
180	            claims.saveAllAndFlush(theirs);
181	            last.cancel(sheets.today(sheetId));
182	            statements.saveAndFlush(last);
183	            audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
184	                    + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().setScale(2).toPlainString()));
185	            return theirs;
186	        });
187	        return new Taken(person, summary(sheetId, personId), unbound);
188	    }
189	}
