9	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk
10	 *  limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
11	 *  DRAFT, OPEN or PENDING claim may be VOID, and a steward may void a SETTLED one within 7 days of
12	 *  its settlement. A DRAFT may be DELETED (counting nowhere), and restored to DRAFT the same day.
13	 *  Opening a claim whose due is above the review threshold leaves it in REVIEW (counting nowhere,
14	 *  with no number) until a steward reviews it (OPEN); a REVIEW claim may be VOID. */
15	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
16	
17	/** The kinds a proof may be; a proof added with none chosen is a receipt. */
18	export const PROOF_KINDS = ['receipt', 'photo'] as const;
19	
20	/** A kind of proof. */
21	export type ProofKind = (typeof PROOF_KINDS)[number];
22	
23	/** A change of status a claim can be asked for. */
24	export type ClaimAction = 'open' | 'settle' | 'resettle' | 'void' | 'approve' | 'reject' | 'delete' | 'restore'
25	  | 'review';
