27	/** Whether a claim is open: OPEN, or PENDING approval of its settle. */
28	export function isOpen(c: Claim): boolean {
29	  return c.status === 'OPEN' || c.status === 'PENDING';
30	}
31	
32	/** Whether a claim at this status counts toward claimed, due-total and every total. */
33	export function counts(c: Claim): boolean {
34	  return isOpen(c) || c.status === 'SETTLED';
35	}
36	
37	/** Whether a claim is deferred on the sheet's today: it is OPEN (or SETTLED while a statement bound
38	 *  it), no statement binds it now, and today is before the day it is deferred until. Until then it
39	 *  counts in no total, is not overdue and cannot be settled. While a statement binds it, the
40	 *  deferral waits until the binding ends. */
41	export function deferred(c: Claim, today: string | null): boolean {
42	  return (c.status === 'OPEN' || c.status === 'SETTLED') && !c.stated
43	    && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
44	}
45	
46	/** Whether a claim counts in the live totals on the sheet's today: it counts, it is not deferred,
47	 *  and it is not an open (or pending) claim, unbound by a statement, of a person retired on that
48	 *  day. A hold does not take it out of any total. */
49	export function countsLive(c: Claim, leave: Leave, today: string | null): boolean {
50	  return counts(c) && !deferred(c, today) && !leftOut(c, leave, today);
51	}
52	
53	/** Whether a claim counts toward what its person has claimed on the sheet's today: it counts, it is
54	 *  not deferred, and it is not an open (or pending) claim, unbound by a statement, of a person
55	 *  retired on that day. A hold does not take it out of claimed. */
56	export function countsClaimed(c: Claim, leave: Leave, today: string | null): boolean {
57	  return counts(c) && !deferred(c, today) && !(isOpen(c) && !c.stated && retiredOn(leave.retiredFrom, today));
58	}
59	
60	/** Whether the live rules leave a claim out: it is open (or pending), unbound by a statement, and
61	 *  its person is retired on the sheet's today. A hold (of the claim or the person) leaves nothing
62	 *  out: it only takes the person's cut out of the pools. */
63	function leftOut(c: Claim, leave: Leave, today: string | null): boolean {
64	  return isOpen(c) && !c.stated && retiredOn(leave.retiredFrom, today);
65	}
66	
67	/** The day (yyyy-mm-dd) a number of days after another (before it when negative). */
68	export function addDays(day: string, days: number): string {
69	  const d = new Date(day + 'T00:00:00Z');
70	  d.setUTCDate(d.getUTCDate() + days);
71	  return d.toISOString().slice(0, 10);
72	}
73	
74	/** Whether a claim keeps its person active on the sheet's today: it is open (or pending), it
75	 *  counts in the live totals, and it is dated within the 30 days up to and including today. */
76	export function keepsActive(c: Claim, leave: Leave, today: string | null): boolean {
77	  return today !== null && isOpen(c) && countsLive(c, leave, today)
78	    && addDays(today, -29) <= c.date && c.date <= today;
79	}
80	
81	/** A claim's part in its patron's backing: its frozen figure when it is settled and dated within
82	 *  the 90 days up to and including the sheet's today; null otherwise. */
83	export function backingFigure(c: Claim, today: string | null): string | null {
84	  return today !== null && c.status === 'SETTLED' && addDays(today, -89) <= c.date && c.date <= today
85	    ? c.settledDue : null;
86	}
87	
88	/** The status a claim had at the end of the day, as its status log records it: that of the last
89	 *  line logged on or before the day; null when it was not yet made then. A claim with no log has
90	 *  its status now. */
91	export function statusOn(c: Claim, day: string): ClaimStatus | null {
92	  if (c.log.length === 0) return c.status;
93	  let then: ClaimStatus | null = null;
94	  for (const line of c.log) if (line.on <= day) then = line.status;
95	  return then;
96	}
97	
98	/** Whether a claim counts in a period's totals: by the status it had at the end of the period's
99	 *  last day it counts, and the live rules do not leave it out: it is not deferred on the sheet's
100	 *  today, and it is not a claim open (or pending) now, unbound by a statement, of a person retired
101	 *  on the sheet's today. */
102	export function countsAsOf(c: Claim, leave: Leave, end: string, today: string | null): boolean {
103	  const then = statusOn(c, end);
104	  if (then === null || !(then === 'OPEN' || then === 'PENDING' || then === 'SETTLED')) return false;
105	  return !deferred(c, today) && !leftOut(c, leave, today);
106	}
