188	/** A share of a claim: the id of the person holding it and their share percent as text with two
189	 *  decimals. The holder's due-total counts their part of the claim's due (see {@link sharePart}),
190	 *  and the claim's own person's the rest. */
191	export interface ClaimShare {
192	  personId: number;
193	  share: string;
194	}
195	
196	/** A share percent: two decimals at most, up to 100.00. */
197	export const SHARE_PCT = /^\d{1,3}(\.\d{1,2})?$/;
198	
199	/** A holder's part of a claim: the claim's amount times their share divided by 100, times the
200	 *  percent of the rate of the holder's own grade (their grade in force on the claim's date) that
201	 *  applies to the claim, divided by 100, rounded like the claim; null when their grade has no rate
202	 *  (a part of 0.00 that is no figure of theirs).
203	 *  A settled claim keeps its parts frozen: its settled figure times the share divided by 100,
204	 *  rounded half to even. */
205	export function sharePart(c: Claim, share: string, rates: Rate[], grade: Grade | undefined, late: Lateness): string | null {
206	  if (c.settledDue !== null) return weightedSum([{ amount: c.settledDue, pct: share }]);
207	  const pct = grade === undefined ? undefined : pctFor(rates, grade, c);
208	  return pct === undefined ? null : sharedDue(c.amount, share, pct, roundsHalfUp(c, late));
209	}
