258	/** An amount with up to two decimals, 0.00 or more. */
259	export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;
260	
261	/** A claim's amount with up to two decimals; a negative one is a correction. */
262	export const CLAIM_AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;
263	
264	/** Whether a claim is a correction: its amount is below 0.00. */
265	export function correction(c: Claim): boolean {
266	  return c.amount.startsWith('-') && Number(c.amount) !== 0;
267	}
268	
269	/** The sum of amounts (two-decimal text), added in cents so no rounding creeps in. */
270	export function sumAmounts(amounts: string[]): string {
271	  const cents = amounts.reduce((sum, a) => sum + Math.round(Number(a) * 100), 0);
272	  return (cents / 100).toFixed(2);
273	}
274	
275	/** Amounts added up, leaving out the single highest and the single lowest when there are three or
276	 *  more. */
277	export function trimmedSum(amounts: string[]): string {
278	  if (amounts.length < 3) return sumAmounts(amounts);
279	  const sorted = [...amounts].sort((a, b) => Number(a) - Number(b));
280	  return sumAmounts(sorted.slice(1, -1));
281	}
