283	/** Whether a claim is bound by its person's last statement now (a pending claim is too, showing
284	 *  and totalling the bound figure). */
285	function bound(c: Claim): boolean {
286	  return c.stated;
287	}
288	
289	/** Whether a claim keeps a figure that rates and grades no longer change: settled or bound by a
290	 *  statement. */
291	export function fixed(c: Claim): boolean {
292	  return c.settledDue !== null || (bound(c) && (c.statedDue !== null || c.statedNa));
293	}
294	
295	/** What a claim's late charge follows: the sheet's today and its late percents (each 30-day boundary
296	 *  takes the one in force on it), and the grace days of each grade; and the sheet's rounding modes and
297	 *  policy date, which decide how its live figures round. */
298	export interface Lateness {
299	  today: string | null;
300	  /** The late percents recorded, each from its from-date, earliest first. */
301	  pcts: DatedValue[];
302	  /** The grace days recorded for each grade. */
303	  graces: Graces;
304	  /** The policy date set (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
305	  policyDate: string | null;
306	  /** The rounding modes recorded (null: blank, none), each from its from-date, earliest first. */
307	  roundings: DatedValue<RoundingMode | null>[];
308	}
309	
310	/** Whether a claim's live figures round half up: by the rounding mode in force on its date, or,
311	 *  when none is, when the date it rounds by is before the policy date in force (the one set, or
312	 *  else the sheet's today); otherwise they round half to even. */
313	export function roundsHalfUp(c: Claim, late: Lateness): boolean {
314	  const mode = valueOn<RoundingMode | null>(late.roundings, c.date, null);
315	  if (mode !== null) return mode === 'half-up';
316	  const policy = late.policyDate ?? late.today;
317	  return policy !== null && c.roundsBy < policy;
318	}
319	
320	/** A claim's due figure: the one fixed when it was settled, or else the one its person's last statement bound it to
321	 *  as it showed then, late charge included (n/a when it bound it to n/a), or else the greater of the sheet's floor in
322	 *  force on the claim's date and its rate figure, with the late charge on that floored figure on top while overdue. The
323	 *  rate figure is its live due at the rate in
324	 *  force on the claim's date that applies to it (see {@link pctFor}) for the grade (the person's grade in force on that date), rounded by the rounding mode or policy date (a
325	 *  settled claim's figure already holds the charge and the floor). A correction has no floor and no late charge. Null
326	 *  when there is none. */
327	export function claimDue(c: Claim, rates: Rate[], grade: Grade | undefined, floors: DatedValue[], late: Lateness): string | null {
328	  if (c.settledDue !== null) return c.settledDue;
329	  if (bound(c) && c.statedNa) return null;
330	  if (bound(c) && c.statedDue !== null) return c.statedDue;
331	  const figure = due(c.amount, grade === undefined ? undefined : pctFor(rates, grade, c), roundsHalfUp(c, late));
332	  if (figure === null) return null;
333	  const floored = correction(c) ? figure : atLeast(figure, valueOn(floors, c.date, STARTING_FLOOR));
334	  return sumAmounts([floored, lateCharge(c, floored, late, grade)]);
335	}
336	
337	/** The late charge on an overdue claim (its grade being its person's grade in force on its date): for each full
338	 *  30 days it is overdue, the late percent in force on that boundary (its late-from plus 30, 60, 90 ... days) of its
339	 *  figure plus the charges of the boundaries before it (the charge compounds), rounded like a due, the charges added
340	 *  up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue, on a correction, and when its
341	 *  late charge is waived. */
342	export function lateCharge(c: Claim, figure: string, late: Lateness, grade: Grade | undefined): string {
343	  if (correction(c) || c.waived) return '0.00';
344	  const grace = graceOn(late.graces, grade, c.date);
345	  if (!overdue(c, late.today, grace) || late.today === null) return '0.00';
346	  const from = Date.parse(lateFrom(c, grace));
347	  const days = (Date.parse(late.today) - from) / 86_400_000;
348	  const periods = Math.floor(days / 30);
349	  if (periods <= 0) return '0.00';
350	  const charges: string[] = [];
351	  for (let n = 1; n <= periods; n++) {
352	    const boundary = new Date(from + n * 30 * 86_400_000).toISOString().slice(0, 10);
353	    const pct = valueOn(late.pcts, boundary, STARTING_LATE_PCT);
354	    if (Number(pct) !== 0) charges.push(due(sumAmounts([figure, ...charges]), pct, roundsHalfUp(c, late)) ?? '0.00');
355	  }
356	  return sumAmounts(charges);
357	}
358	
359	/** The day a claim's lateness counts from: its due-by plus its grace days (those in force on its date
360	 *  for its person's grade in force on that date). The due-by it shows is unchanged. */
361	export function lateFrom(c: Claim, grace: number): string {
362	  return grace === 0 ? c.dueBy : addDays(c.dueBy, grace);
363	}
364	
365	/** Whether a claim in review is late: its review day (the sheet's today when it last went to review)
366	 *  plus the sheet's review SLA days is before the sheet's today; never while there is no SLA. */
367	export function reviewLate(c: Claim, today: string | null, sla: number | null): boolean {
368	  if (c.status !== 'REVIEW' || today === null || sla === null) return false;
369	  const day = c.log.filter((l) => l.status === 'REVIEW').at(-1)?.on;
370	  return day !== undefined && addDays(day, sla) < today;
371	}
372	
373	/** Whether a pending claim is late: its pending day (the sheet's today when it last went to pending)
374	 *  plus the sheet's pending SLA days is before the sheet's today; never while there is no SLA. */
375	export function pendingLate(c: Claim, today: string | null, sla: number | null): boolean {
376	  if (c.status !== 'PENDING' || today === null || sla === null) return false;
377	  const day = c.log.filter((l) => l.status === 'PENDING').at(-1)?.on;
378	  return day !== undefined && addDays(day, sla) < today;
379	}
380	
381	/** Whether a claim is overdue: it is open (or pending), not deferred, and its due-by plus its grace
382	 *  days is before the sheet's today. */
383	export function overdue(c: Claim, today: string | null, grace = 0): boolean {
384	  return isOpen(c) && !deferred(c, today) && today !== null && lateFrom(c, grace) < today;
385	}
