7	/** A grade's code: A, B, C or one added to the sheet (one to three capital letters). */
8	export type Grade = string;
9	
10	/** A grade a person was given, from a day (yyyy-mm-dd); null: from the beginning of time. */
11	export interface GradeFrom {
12	  grade: Grade;
13	  from: string | null;
14	}
15	
16	/** The grade in force on a day: the one with the latest from-date on or before it, or else the one
17	 *  with no from-date; grades come earliest first. */
18	export function gradeOn(grades: GradeFrom[], day: string | null): Grade | undefined {
19	  let on: Grade | undefined;
20	  for (const g of grades) {
21	    if (g.from === null || (day !== null && g.from <= day)) on = g.grade;
22	  }
23	  return on;
24	}
25	
26	/** A person's name as the screen shows it: <name> (<grade in force on the day>). */
27	export function shownName(p: { name: string; grade: Grade; grades: GradeFrom[] }, day: string | null): string {
28	  return `${p.name} (${gradeOn(p.grades, day) ?? p.grade})`;
29	}
30	
31	/** A hold on a person from a day (null: from the beginning of time) to a day (null: open-ended),
32	 *  both included (yyyy-mm-dd). */
33	export interface Hold {
34	  from: string | null;
35	  to: string | null;
36	}
37	
38	/** What leaves a person's open claims, unbound by a statement, out of the live totals: their
39	 *  holds, and their retirement once the sheet's today reaches it. */
40	export interface Leave {
41	  holds: Hold[];
42	  retiredFrom: string | null;
43	}
44	
45	/** Whether a person retired from a day (null: not retired) is retired on another. */
46	export function retiredOn(retiredFrom: string | null, day: string | null): boolean {
47	  return retiredFrom !== null && day !== null && retiredFrom <= day;
48	}
49	
50	/** Whether one of the holds covers a day. */
51	export function heldOn(holds: Hold[], day: string): boolean {
52	  return holds.some((h) => (h.from === null || h.from <= day) && (h.to === null || day <= h.to));
53	}
54	
55	/** A past retirement of a person: from the day they were retired from to the day they were
56	 *  unretired (yyyy-mm-dd). */
57	export interface Retirement {
58	  from: string;
59	  to: string;
60	}
61	
62	/** A statement of a person that stands: its date (yyyy-mm-dd) and their due-total in it (two
63	 *  decimals; null when it was n/a). */
64	export interface StatementLine {
65	  date: string;
66	  dueTotal: string | null;
67	}
68	
69	/** A snapshot of a person: the day being left (yyyy-mm-dd) and their due-total on it (two
70	 *  decimals, or n/a). */
71	export interface Snapshot {
72	  day: string;
73	  dueTotal: string;
74	}
75	
76	export interface Person {
77	  id: number;
78	  name: string;
79	  /** The grade in force on the sheet's today when the person was read. */
80	  grade: Grade;
81	  /** Every grade recorded for them, earliest first. */
82	  grades: GradeFrom[];
83	  /** Raised each time the person is saved. */
84	  version: number;
85	  /** How many statements were taken of them. */
86	  statementCount: number;
87	  /** The last statement's due-total as text with two decimals; null when it was n/a or none was taken. */
88	  statedTotal: string | null;
89	  /** The day (yyyy-mm-dd) the last statement was taken; null when none was. */
90	  statementDate: string | null;
91	  /** Whether they are retired: they are as soon as a retirement day is set, whatever the day. */
92	  retired: boolean;
93	  /** The day (yyyy-mm-dd) they are retired from; null when they are not retired. */
94	  retiredFrom: string | null;
95	  /** Their past retirements, earliest first. */
96	  retirements: Retirement[];
97	  /** Whether they have any hold, whatever its days. */
98	  held: boolean;
99	  /** Their holds, earliest first: their open claims dated within one count in no live total. */
100	  holds: Hold[];
101	  /** Their own terms in force on the sheet's today in days, ahead of their grade's and the sheet's;
