344	/** A person's timeline: a line for each dated thing about them, in date order, and on a day their
345	 *  grade changes, then their claims, then their holds, then their retirements, then their
346	 *  unretirements (those of a kind on a day in the order of their lines):
347	 *  <date> grade <grade>, <date> claim <amount> <status>, <date> hold [to <date>], <date> retired,
348	 *  <date> unretired. A grade or hold with no from-date has no line. */
349	export function timelineOf(p: Person, claims: Claim[]): string[] {
350	  const items: { date: string; rank: number; line: string }[] = [];
351	  const add = (date: string | null, rank: number, what: string) => {
352	    if (date !== null) items.push({ date, rank, line: `${date} ${what}` });
353	  };
354	  for (const g of p.grades) add(g.from, 0, `grade ${g.grade}`);
355	  for (const c of claims) add(c.date, 1, `claim ${c.amount} ${c.status}`);
356	  for (const h of p.holds) add(h.from, 2, h.to === null ? 'hold' : `hold to ${h.to}`);
357	  for (const r of p.retirements) add(r.from, 3, 'retired');
358	  add(p.retiredFrom, 3, 'retired');
359	  for (const r of p.retirements) add(r.to, 4, 'unretired');
360	  const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
361	  return items
362	    .sort((a, b) => cmp(a.date, b.date) || a.rank - b.rank || cmp(a.line, b.line))
363	    .map((i) => i.line);
364	}
