8	/** What a person's statements come to: how many were taken (those carried to them with a merge or a
9	 *  transfer too), and the last one's due-total (null when
10	 *  it was n/a) and date (the day it was taken as of); both null when none was taken; and every one of
11	 *  them, oldest first by its date (those of a day in the order they were taken). */
12	public record StatementSummary(int count, BigDecimal lastDueTotal, LocalDate lastTakenOn, List<Line> lines) {
13	
14	    public static final StatementSummary NONE = new StatementSummary(0, null, null, List.of());
15	
16	    /** One statement: its date (the day it was taken as of) and its due-total (null when it was n/a). */
17	    public record Line(LocalDate date, BigDecimal dueTotal) {
18	    }
19	
20	    /** The summary of one person's statements, given in the order they were taken. */
21	    public static StatementSummary of(List<Statement> statements) {
22	        if (statements.isEmpty()) {
23	            return NONE;
24	        }
25	        Statement last = last(statements);
26	        List<Line> lines = statements.stream()
27	                .sorted(Comparator.comparing(Statement::getStatedOn))
28	                .map(st -> new Line(st.getStatedOn(), st.getDueTotal()))
29	                .toList();
30	        return new StatementSummary(statements.size(), last.getDueTotal(), last.getStatedOn(), lines);
31	    }
32	
33	    /** A person's last statement, of theirs given in the order they were taken: the last of their
34	     *  own, or, having none, the last one carried to them; null when there are none. */
35	    public static Statement last(List<Statement> statements) {
36	        Statement last = null;
37	        for (Statement s : statements) {
38	            if (last == null || !s.isCarried() || last.isCarried()) {
39	                last = s;
40	            }
41	        }
42	        return last;
43	    }
44	}
