1	import { Pipe, PipeTransform, inject } from '@angular/core';
2	import { Session } from './session';
3	
4	const FIGURE = /^(-?)(\d+)\.(\d{2})$/;
5	
6	/** A figure (a number with two decimals, as the store gives it) as the user's locale shows it:
7	 *  en 1234.56, de 1.234,56. Anything else is shown as it is. */
8	export function formatFigure(value: string, locale: string): string {
9	  const m = locale === 'de' ? FIGURE.exec(value) : null;
10	  if (!m) return value;
11	  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+(?!\d))/g, '.')},${m[3]}`;
12	}
13	
14	/** Shows a figure in the signed-in user's locale; impure so a change of locale re-renders it. */
15	@Pipe({ name: 'figure', pure: false })
16	export class FigurePipe implements PipeTransform {
17	  private readonly session = inject(Session);
18	
19	  transform(value: string | number | null | undefined): string {
20	    if (value === null || value === undefined) return '';
21	    return formatFigure(String(value), this.session.locale());
22	  }
23	}
