1	import { HttpErrorResponse } from '@angular/common/http';
2	import { Component, effect, inject, input, output, signal, untracked } from '@angular/core';
3	import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
4	import { AMOUNT, CLAIM_AMOUNT, Claim, ClaimAction, Claims, PROOF_KINDS, SHARE_PCT, ProofKind, claimDue, deferred, overdue, pendingLate, reviewLate } from '../../core/claims';
5	import { ClaimTemplates } from '../../core/claim-templates';
6	import { GradeFrom, Person, gradeOn } from '../../core/people';
7	import { Period, periodOf } from '../../core/periods';
8	import { Rate } from '../../core/rates';
9	import { Session } from '../../core/session';
10	import { VoidReasons } from '../../core/void-reasons';
11	import { DatedValue, Graces, PolicyVersion, RoundingMode, graceOn, policyOn } from '../../core/settings';
12	import { FigurePipe } from '../../core/figure';
13	import { AuditLog } from '../../core/audit-log';
14	
15	/** Why the server refused an action: the claim's status does not allow it. */
16	const REFUSALS: Record<ClaimAction, string> = {
17	  open: 'Only a draft claim can be opened, and only while its person is under its period\'s cap of open claims.',
18	  settle: 'Only an open claim that is not deferred can be settled.',
19	  resettle: 'Only a settled claim can be re-settled.',
20	  void: 'Only a draft, review, open or pending claim can be voided, or a settled one within 7 days of its settlement.',
21	  approve: 'Only a pending claim can be approved.',
22	  reject: 'Only a pending claim can be rejected.',
23	  delete: 'Only a draft claim can be deleted.',
24	  restore: 'Only a deleted claim can be restored, on the day it was deleted.',
25	  review: 'Only a claim in review can be reviewed.',
26	};
27	
28	/** The message when an edit of a claim that is not a draft is refused. */
29	const NOT_DRAFT = 'Only a draft claim can be edited; void an open claim and add a new one.';
30	
31	/** The message when another user has the claim's editor open. */
32	const EDIT_LOCKED = 'Another user is editing this claim; try again once they save or cancel.';
33	
34	/** The message for a refused opening of a claim's editor. */
35	function editorRefusal(e: unknown, c: Claim): string {
36	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
37	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not edit a claim.';
38	  if (e instanceof HttpErrorResponse && e.status === 409) return c.status === 'DRAFT' ? EDIT_LOCKED : NOT_DRAFT;
39	  return 'The claim\'s editor could not be opened.';
40	}
41	
42	/** The message when the server refused a change to a claim dated inside a closed period. */
43	const CLOSED = 'The claim\'s period is closed.';
44	const RETIRED = 'A claim cannot be dated after the person\'s retirement.';
45	const CORRECTS = 'A negative amount must name the number of a settled claim of this person.';
46	const REF_USED = 'That reference is already used on this sheet.';
47	const REF_LONG = 'Enter a reference of at most 120 characters.';
48	
49	/** The message for a refused action on a claim. */
50	function refusal(e: unknown, action: ClaimAction): string {
51	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
52	  if (e instanceof HttpErrorResponse && e.status === 409) return REFUSALS[action];
53	  if (e instanceof HttpErrorResponse && e.status === 428) return NEEDS_PROOF;
54	  if (e instanceof HttpErrorResponse && e.status === 422 && action === 'open') {
55	    return 'A claim whose due is above the note threshold needs a note before it is opened.';
56	  }
57	  if (e instanceof HttpErrorResponse && e.status === 400 && action === 'settle') {
58	    return 'Enter a date on or before the sheet\'s today on which the claim already existed.';
59	  }
60	  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'settle') {
61	    return 'The user who opened or last edited a claim cannot settle it.';
62	  }
63	  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'void') {
64	    return 'Your role may not void this claim; only a steward may void a settled claim.';
65	  }
66	  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'review') {
67	    return 'Only a steward can review a claim.';
68	  }
69	  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'resettle') {
70	    return 'Only a steward can re-settle a claim.';
71	  }
72	  if (e instanceof HttpErrorResponse && e.status === 403 && (action === 'approve' || action === 'reject')) {
73	    return action === 'approve'
74	      ? "Only a steward or the person's approver who did not open or last edit the claim can approve it."
75	      : "Only a steward or the person's approver can reject a claim.";
76	  }
77	  if (e instanceof HttpErrorResponse && e.status === 400 && action === 'reject') {
78	    return 'Enter a reason for rejecting the claim.';
79	  }
80	  if (e instanceof HttpErrorResponse && e.status === 400 && action === 'void') {
81	    return 'Choose a void reason from the sheet\'s list.';
82	  }
83	  return 'The claim could not be changed.';
84	}
85	
86	/** The message when a claim due above the proof threshold has no proof to be settled or approved. */
87	const NEEDS_PROOF = 'The claim\'s due is above the proof threshold: add a proof (of each proof kind the sheet lists) first.';
88	
89	/** The message for a refused proof of a claim. */
90	function proofRefusal(e: unknown): string {
91	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
92	  if (e instanceof HttpErrorResponse && e.status === 409) return 'A settled or void claim cannot be given a proof.';
93	  return 'The proof could not be added.';
94	}
95	
96	/** The message for a refused reminder of a claim. */
97	function remindRefusal(e: unknown): string {
98	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only an open or pending claim can be reminded.';
99	  if (e instanceof HttpErrorResponse && e.status === 429) return 'The claim was already reminded today.';
100	  return 'The reminder could not be sent.';
101	}
102	
103	/** The message when a comment's text is empty. */
104	const COMMENT_EMPTY = 'Enter the text of the comment.';
105	
106	/** The message for a refused comment on a claim. */
107	function commentRefusal(e: unknown): string {
108	  if (e instanceof HttpErrorResponse && e.status === 400) return COMMENT_EMPTY;
109	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not comment on a claim.';
110	  return 'The comment could not be added.';
111	}
112	
113	/** The message when a line's label, quantity or unit amount is not valid. */
114	const LINE_INVALID = 'Enter a label, a whole quantity of at least 1 and a unit amount above 0.00 with two decimals at most.';
115	
116	/** The message for a refused line on a claim. */
117	function lineRefusal(e: unknown): string {
118	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
119	  if (e instanceof HttpErrorResponse && e.status === 409) {
120	    return 'Only a draft claim no one else is editing can be given a line.';
121	  }
122	  if (e instanceof HttpErrorResponse && e.status === 400) return LINE_INVALID;
123	  return 'The line could not be added.';
124	}
125	
126	/** The message for a refused defer of a claim. */
127	function deferRefusal(e: unknown): string {
128	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
129	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only an open claim can be deferred.';
130	  if (e instanceof HttpErrorResponse && e.status === 400) return DEFER_DATE;
131	  return 'The claim could not be deferred.';
132	}
133	
134	/** The message for a refused waiver of a claim's late charge. */
135	function waiveRefusal(e: unknown): string {
136	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Only a steward can waive a late charge.';
137	  if (e instanceof HttpErrorResponse && e.status === 409) {
138	    return 'Only an open or pending claim not waived already can have its late charge waived.';
139	  }
140	  return 'The late charge could not be waived.';
141	}
142	
143	/** The message for a refused hold or release of a claim. */
144	function holdRefusal(e: unknown): string {
145	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only an open or pending claim can be held or released.';
146	  return 'The claim could not be held or released.';
147	}
148	
149	/** The message for a refused review assignment of a claim. */
150	function assignReviewRefusal(e: unknown): string {
151	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Only a steward can assign a review.';
152	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only a claim in REVIEW can be assigned.';
153	  if (e instanceof HttpErrorResponse && e.status === 400) return REVIEW_USER;
154	  return 'The review could not be assigned.';
155	}
156	
157	/** The message when a review assignment's user is missing. */
158	const REVIEW_USER = 'Enter the user to assign the review to.';
159	
160	/** The message for a refused re-date of a claim. */
161	function redateRefusal(e: unknown): string {
162	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Only a steward can re-date a claim.';
163	  if (e instanceof HttpErrorResponse && e.status === 423) return 'That claim\'s period is closed.';
164	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only an open or pending claim can be re-dated.';
165	  if (e instanceof HttpErrorResponse && e.status === 422) return 'A claim cannot be dated after the person\'s retirement.';
166	  if (e instanceof HttpErrorResponse && e.status === 400) return REDATE_DATE;
167	  return 'The claim could not be re-dated.';
168	}
169	
170	/** The message when a re-date's date is missing. */
171	const REDATE_DATE = 'Enter the new date for the claim.';
172	
173	/** The message for a refused setting of a claim's due-by. */
174	function dueByRefusal(e: unknown): string {
175	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Only a steward can set a claim\'s due-by.';
176	  if (e instanceof HttpErrorResponse && e.status === 423) return 'That claim\'s period is closed.';
177	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only a draft, open or pending claim\'s due-by can be set.';
178	  if (e instanceof HttpErrorResponse && e.status === 400) return DUE_BY_DATE;
179	  return 'The claim\'s due-by could not be set.';
180	}
181	
182	/** The message when a due-by's date is missing. */
183	const DUE_BY_DATE = 'Enter the new due-by for the claim.';
184	
185	/** The message when a defer's date is missing or not after the sheet's today. */
186	const DEFER_DATE = 'Enter a date after the sheet\'s today to defer the claim to.';
187	
188	/** The message when a row's amount entry is not an amount. */
189	const INLINE_AMOUNT = 'Enter an amount with up to two decimals; a negative amount is a correction.';
190	
191	/** The message when an edit types another amount than the total of a claim's lines. */
192	const LINED = 'A claim with lines has their total as its amount; add a line to change it.';
193	
194	/** The message for a refused change of a claim's amount from its row. */
195	function amountRefusal(e: unknown, c: Claim, amount: string): string {
196	  if (e instanceof HttpErrorResponse && e.status === 400 && c.lines.length > 0) return LINED;
197	  if (e instanceof HttpErrorResponse && e.status === 400 && amount.startsWith('-')) return CORRECTS;
198	  if (e instanceof HttpErrorResponse && e.status === 422) return RETIRED;
199	  if (e instanceof HttpErrorResponse && (e.status === 403 || e.status === 409 || e.status === 423)) {
200	    return editorRefusal(e, c);
201	  }
202	  return 'The claim\'s amount could not be saved.';
203	}
204	
205	/** The message when a share percent is not above 0.00 with two decimals at most. */
206	const SHARE_INVALID = 'Enter a share percent above 0.00 with up to two decimals.';
207	
208	/** The message when a claim would be shared with its own person, or twice with one person. */
209	const SHARE_HOLDER = 'A claim cannot be shared with its own person, nor twice with one person.';
210	
211	/** The message for a refused share of a claim. */
212	function shareRefusal(e: unknown): string {
213	  if (e instanceof HttpErrorResponse && e.status === 400) return SHARE_INVALID;
214	  if (e instanceof HttpErrorResponse && e.status === 422) return 'A claim\'s shares cannot add up to more than 100.00.';
215	  if (e instanceof HttpErrorResponse && e.status === 409) {
216	    return 'Only a claim that is not settled, void or deleted can be shared, and not with its own person or twice with one person.';
217	  }
218	  return 'The claim could not be shared.';
219	}
220	
221	/** The message for a refused reassign of a claim. */
222	function reassignRefusal(e: unknown): string {
223	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Only a steward can reassign a claim.';
224	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only a draft, open or pending claim can be reassigned.';
225	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
226	  if (e instanceof HttpErrorResponse && e.status === 422) return 'The claim is dated after that person\'s retirement.';
227	  return 'The claim could not be reassigned.';
228	}
229	
230	/** The message when a split's amount is not above 0.00 and below the claim's amount. */
231	const SPLIT_AMOUNT = 'Enter an amount above 0.00 and below the claim\'s amount to split off.';
232	
233	/** The message for a refused split of a claim. */
234	function splitRefusal(e: unknown): string {
235	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
236	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only an open claim that is not deferred can be split.';
237	  if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not open a claim, so it cannot split one.';
238	  if (e instanceof HttpErrorResponse && e.status === 400) return SPLIT_AMOUNT;
239	  return 'The claim could not be split.';
240	}
241	
242	/** The message for a refused part-settle of a claim. */
243	function settlePartRefusal(e: unknown): string {
244	  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
245	  if (e instanceof HttpErrorResponse && e.status === 409) return 'Only an open claim that is not deferred can be part-settled.';
246	  if (e instanceof HttpErrorResponse && e.status === 403) return 'You may not split or settle this claim.';
247	  if (e instanceof HttpErrorResponse && e.status === 428) return 'The claim needs its proofs before it can be settled.';
248	  if (e instanceof HttpErrorResponse && e.status === 400) return SPLIT_AMOUNT;
249	  return 'The claim could not be part-settled.';
250	}
