252	// A person's claims, newest first, and the form that adds a claim for them or, once a claim's
253	// editor is opened, edits it.
254	@Component({
255	  selector: 'app-person-claims',
256	  imports: [ReactiveFormsModule, FigurePipe],
257	  template: `
258	    <form data-testid="claim-form" [formGroup]="form" (ngSubmit)="submit()">
259	      <label [for]="'claim-form-amount-' + personId()">Amount</label>
260	      <input [id]="'claim-form-amount-' + personId()" data-testid="claim-form-amount" formControlName="amount"
261	        inputmode="decimal" />
262	      <label [for]="'claim-form-date-' + personId()">Date</label>
263	      <input [id]="'claim-form-date-' + personId()" type="date" data-testid="claim-form-date" formControlName="date" />
264	      <label [for]="'claim-form-note-' + personId()">Note</label>
265	      <input [id]="'claim-form-note-' + personId()" data-testid="claim-form-note" formControlName="note" />
266	      <label [for]="'claim-form-corrects-' + personId()">Corrects claim number</label>
267	      <input [id]="'claim-form-corrects-' + personId()" data-testid="claim-form-corrects" formControlName="corrects"
268	        inputmode="numeric" />
269	      <label [for]="'claim-form-ref-' + personId()">Reference</label>
270	      <input [id]="'claim-form-ref-' + personId()" data-testid="claim-form-ref" formControlName="ref" />
271	      <label [for]="'claim-form-tags-' + personId()">Tags (comma separated)</label>
272	      <input [id]="'claim-form-tags-' + personId()" data-testid="claim-form-tags" formControlName="tags" />
273	      <button type="submit" data-testid="claim-form-submit">{{ editing() === null ? 'Add claim' : 'Save claim' }}</button>
274	      <label [for]="'claim-template-select-' + personId()">Template</label>
275	      <select [id]="'claim-template-select-' + personId()" data-testid="claim-template-select" #template
276	        (change)="error.set('')">
277	        <option value="">Choose a template</option>
278	        @for (t of templates.list(); track t.id) {
279	          <option [value]="t.name">{{ t.name }}</option>
280	        }
281	      </select>
282	      <button type="button" data-testid="claim-template-add" (click)="addFromTemplate(template.value)">
283	        Add claim from template</button>
284	      @if (error()) {
285	        <p role="alert" data-testid="claim-form-error">{{ error() }}</p>
286	      }
287	    </form>
288	    <ul data-testid="claims">
289	      @for (c of claims(); track c.id) {
290	        <li [attr.data-testid]="'claim-row-' + c.id">
291	          <input type="checkbox" data-testid="claim-select" [checked]="selected().has(c.id)"
292	            (change)="selectedChange.emit({ id: c.id, selected: $any($event.target).checked })"
293	            [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
294	          <span data-testid="claim-number">{{ c.number ?? '' }}</span>
295	          <span data-testid="claim-amount">{{ c.amount | figure }}</span>
296	          <span data-testid="claim-date">{{ c.date }}</span>
297	          <span data-testid="claim-note">{{ c.note }}</span>
298	          <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span>
299	          <span data-testid="claim-ref">{{ c.ref ?? '' }}</span>
300	          <span data-testid="claim-tags">{{ c.tags }}</span>
301	          <span data-testid="claim-due">{{ dueOf(c) | figure }}</span>
302	          <span data-testid="claim-policy">{{ policyOf(c) }}</span>
303	          <span data-testid="claim-status">{{ c.status }}</span>
304	          <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span>
305	          <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span>
306	          <span data-testid="claim-period">{{ periodName(c) }}</span>
307	          <span data-testid="claim-late-entry">{{ c.lateEntry ? 'yes' : 'no' }}</span>
308	          <span data-testid="claim-due-by">{{ dueByOf(c) }}</span>
309	          <span data-testid="claim-review-late">{{ reviewLateOf(c) ? 'yes' : 'no' }}</span>
310	          <span data-testid="claim-pending-late">{{ pendingLateOf(c) ? 'yes' : 'no' }}</span>
