931	  protected async submit(): Promise<void> {
932	    if (this.submitting) return;
933	    this.error.set('');
934	    this.claimError.set(null);
935	    const { amount, date, note, corrects, ref, tags } = this.form.getRawValue();
936	    if (!CLAIM_AMOUNT.test(amount.trim())) {
937	      this.error.set('Enter an amount with up to two decimals; a negative amount is a correction.');
938	      return;
939	    }
940	    const number = corrects.trim();
941	    if (number.length > 120) {
942	      this.error.set(CORRECTS);
943	      return;
944	    }
945	    const reference = ref.trim();
946	    if (reference.length > 120) {
947	      this.error.set(REF_LONG);
948	      return;
949	    }
950	    const day = date.trim();
951	    if (day !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(day)) {
952	      this.error.set('Enter a date, or leave it blank for the sheet\'s today.');
953	      return;
954	    }
955	    const form = {
956	      amount: amount.trim(), date: day === '' ? null : day, note, corrects: number === '' ? null : number,
957	      ref: reference === '' ? null : reference, tags,
958	    };
959	    const id = this.editing();
960	    this.submitting = true;
961	    try {
962	      const claim = id === null ? await this.api.add(this.personId(), form) : await this.api.edit(id, form);
963	      this.saved.emit(claim);
964	      this.reset();
965	    } catch (e) {
966	      if (e instanceof HttpErrorResponse && e.status === 423) this.error.set(CLOSED);
967	      else if (e instanceof HttpErrorResponse && e.status === 422) this.error.set(RETIRED);
968	      else if (e instanceof HttpErrorResponse && e.status === 400 && id !== null
969	        && (this.claims().find((x) => x.id === id)?.lines.length ?? 0) > 0) {
970	        // Its lines fix its amount, so no save of the editor can go through: close it (unlocking
971	        // the claim), the form back to adding, and show why.
972	        await this.cancel();
973	        this.error.set(LINED);
974	      }
975	      else if (e instanceof HttpErrorResponse && e.status === 400 && amount.trim().startsWith('-')) this.error.set(CORRECTS);
976	      else if (e instanceof HttpErrorResponse && e.status === 409 && reference !== '' && this.refClash(id)) {
977	        this.error.set(REF_USED);
978	      }
979	      else if (id !== null && e instanceof HttpErrorResponse && e.status === 409) {
980	        const c = this.claims().find((x) => x.id === id);
981	        this.claimError.set({ id, message: c ? editorRefusal(e, c) : NOT_DRAFT });
982	      }
983	      else this.error.set(id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
984	    } finally {
985	      this.submitting = false;
986	    }
987	  }
