1014	  /** Whether a conflict on saving the form (an add when `id` is null) can only be its reference
1015	   *  being in use: an add, or an edit of a draft no other user is editing. */
1016	  private refClash(id: number | null): boolean {
1017	    if (id === null) return true;
1018	    const c = this.claims().find((x) => x.id === id);
1019	    return c !== undefined && c.status === 'DRAFT'
1020	      && (c.editLockedBy === null || c.editLockedBy === this.session.user());
1021	  }
