7	export interface Rate {
8	  grade: Grade;
9	  /** The percent as text with two decimals. */
10	  pct: string;
11	  /** The day (yyyy-mm-dd) the rate applies from; null when it applies from the beginning of time. */
12	  from: string | null;
13	  /** The last day (yyyy-mm-dd) the rate applies; null when it has no end. */
14	  to: string | null;
15	  /** The sheet the rate is set on: 0 for this sheet, 1 for its parent, 2 for the parent's parent,
16	   *  and so on. */
17	  level: number;
18	  /** How many versions the rate has had; this is the newest, the one in force. */
19	  version: number;
20	  /** Where a forward-only rate (one saved with a from-date on or after the sheet's today) was saved
21	   *  in the order claims are added: it applies only to claims added after it. Null when it applies
22	   *  to every claim. */
23	  forwardAfter: number | null;
24	  /** The rate's older versions, the newest first. */
25	  older: RateVersion[];
26	}
27	
28	/** An older version of a rate: its percent and to-date, and where it was saved when it was
29	 *  forward-only (see {@link Rate}). */
30	export interface RateVersion {
31	  pct: string;
32	  to: string | null;
33	  forwardAfter: number | null;
34	}
35	
36	/** What a candidate rate would change: how many open and pending claims would show a different
37	 *  due, and the sum of the differences as two-decimal text (negative when lower). */
38	export interface RatePreview {
39	  count: number;
40	  diff: string;
41	}
