43	/** The percent of a grade's rate in force on a day: on this sheet, or else, when it has none in
44	 *  force on it, on the nearest ancestor that has (see {@link levelPctOn}); undefined when none has. */
45	export function pctOn(rates: Rate[], grade: Grade, day: string): string | undefined {
46	  const levels = [...new Set(rates.map((r) => r.level))].sort((a, b) => a - b);
47	  for (const level of levels) {
48	    const pct = levelPctOn(rates.filter((r) => r.level === level), grade, day);
49	    if (pct !== undefined) return pct;
50	  }
51	  return undefined;
52	}
53	
54	/** The percent of a grade's rate that applies to a claim: as {@link pctOn} on the claim's date, each
55	 *  rate taken as the newest of its versions that applies to the claim (a forward-only one only to a
56	 *  claim added after it was saved), and passed over when none does. */
57	export function pctFor(rates: Rate[], grade: Grade, claim: { date: string; added: number }): string | undefined {
58	  const applying = rates.flatMap((r) => {
59	    const version = [r, ...r.older].find((v) => v.forwardAfter === null || claim.added > v.forwardAfter);
60	    return version === undefined ? [] : [{ ...r, pct: version.pct, to: version.to }];
61	  });
62	  return pctOn(applying, grade, claim.date);
63	}
64	
65	/** The percent of a grade's rate in force on a day among the rates of one sheet: the rate with the
66	 *  latest from-date on or before it, or else the one with no from-date; undefined when the day is
67	 *  before every rate, or after the to-date of that rate. */
68	function levelPctOn(rates: Rate[], grade: Grade, day: string): string | undefined {
69	  let best: Rate | undefined;
70	  for (const r of rates) {
71	    if (r.grade !== grade || (r.from !== null && r.from > day)) continue;
72	    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
73	  }
74	  if (best?.to != null && best.to < day) return undefined;
75	  return best?.pct;
76	}
77	
78	/** A percent with up to two decimals, 0.00 or more. */
79	export const PCT = /^\d{1,5}(\.\d{1,2})?$/;
80	
81	/** Two-decimal text, which may be negative, as a whole number of hundredths. */
82	function hundredths(text: string): bigint {
83	  const negative = text.startsWith('-');
84	  const [whole, frac = ''] = (negative ? text.slice(1) : text).split('.');
85	  const n = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
86	  return negative ? -n : n;
87	}
88	
89	/** An amount's due at a percent: amount times pct divided by 100, rounded to two decimals half to
90	 *  even, or half up (away from zero) when `halfUp`, worked in whole numbers so no rounding creeps
91	 *  in; a negative amount has a negative due. Null when there is no rate. */
92	export function due(amount: string, pct: string | undefined, halfUp = false): string | null {
93	  if (pct === undefined) return null;
94	  return weighted(hundredths(amount) * hundredths(pct), halfUp);
95	}
96	
97	/** Amounts each times a percent divided by 100, added up exactly and then rounded to two decimals
98	 *  half to even. */
99	export function weightedSum(parts: { amount: string; pct: string }[]): string {
100	  return weighted(parts.reduce((sum, x) => sum + hundredths(x.amount) * hundredths(x.pct), 0n), false);
101	}
102	
103	/** An amount's part at a share percent and a rate percent: amount times share divided by 100, times
104	 *  pct divided by 100, rounded once to two decimals half to even, or half up when `halfUp`. */
105	export function sharedDue(amount: string, share: string, pct: string, halfUp = false): string {
106	  return weighted(hundredths(amount) * hundredths(share) * hundredths(pct), halfUp, 100000000n);
107	}
108	
109	/** A product of hundredths (by default two, so in ten-thousandths of a hundredth) rounded to
110	 *  two-decimal text: `per` units of the product make one hundredth. */
111	function weighted(signed: bigint, halfUp: boolean, per = 10000n): string {
112	  const exact = signed < 0n ? -signed : signed;
113	  let cents = exact / per;
114	  const rest = exact % per;
115	  const half = per / 2n;
116	  if (rest > half || (rest === half && (halfUp || cents % 2n === 1n))) cents += 1n;
117	  const text = cents.toString().padStart(3, '0');
118	  return `${signed < 0n && cents > 0n ? '-' : ''}${text.slice(0, -2)}.${text.slice(-2)}`;
119	}
120	
121	/** The larger of two two-decimal figures. */
122	export function atLeast(figure: string, floor: string): string {
123	  return hundredths(figure) < hundredths(floor) ? floor : figure;
124	}
