125	    /** The next claim number on the sheet for a claim due by the day: <FY>-<n>, counting from 1 within
126	     *  the fiscal year (by the sheet's fiscal start month) the day falls in; the sheets of a tree share
127	     *  one sequence per fiscal year, so it is the next after the last number given within that fiscal
128	     *  year on any sheet of the sheet's tree. */
129	    @Transactional
130	    public String nextClaimNumber(String id, LocalDate dueBy) {
131	        // the tree's root row is locked until the transaction ends, so two claims opened on its
132	        // sheets at once get one number each
133	        String root = sheets.root(id);
134	        sheets.lockClaimNumber(root);
135	        if (sheets.lockClaimNumber(id) != 1) {
136	            throw new IllegalStateException("No sheet " + id);
137	        }
138	        String fiscalYear = PeriodService.fiscalYear(dueBy, fiscalStartMonth(id));
139	        List<String> tree = new ArrayList<>(sheets.descendants(root));
140	        tree.add(root);
141	        int next = fiscalNumbers.lastNumber(tree, fiscalYear) + 1;
142	        FiscalClaimNumber last = fiscalNumbers.findById(new FiscalClaimNumber.Key(id, fiscalYear))
143	                .orElseGet(() -> new FiscalClaimNumber(id, fiscalYear, 0));
144	        last.setLastNumber(next);
145	        fiscalNumbers.saveAndFlush(last);
146	        return fiscalYear + "-" + next;
147	    }
