176	    /** Change the sheet's today, first recording each person's due-total on the day being left,
177	     *  closing every claim editor held open on it
178	     *  when the day is a new one; then, when the sheet has grace days, close
179	     *  the open periods they have run out on; then the figures it moves are recorded. */
180	    @Transactional
181	    public synchronized Sheet setToday(String id, String user, LocalDate today) {
182	        Sheet sheet = load(id, user);
183	        if (!roles.may(id, user, "today")) {
184	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not change the sheet's today");
185	        }
186	        if (!today.equals(sheet.getToday())) {
187	            claims.releaseEditLocks(id);
188	        }
189	        if (sheet.isScoreLog()) {
190	            rollup.recordScores(id, user);
191	        }
192	        rollup.recordSnapshot(id, user);
193	        return rollup.tracking(id, user, () -> {
194	            sheet.setToday(today);
195	            Sheet saved = sheets.saveAndFlush(sheet);
196	            if (saved.getGraceDays() != null) {
197	                periods.autoClose(id, user, saved.getGraceDays(), today);
198	            }
199	            return saved;
200	        });
201	    }
