224	    /** Record a dated setting's value from a date (the sheet's today when none is given), keeping the
225	     *  values already recorded (one from the same date is replaced); recorded in the audit even when
226	     *  it is unchanged, with the from-date at the end when one was given. A policy setting (see
227	     *  {@link PolicyVersion#KEYS}) makes a new policy version from that date. */
228	    private Sheet record(String id, String user, String key, BigDecimal value, String shown, LocalDate from) {
229	        Sheet sheet = load(id, user);
230	        LocalDate on = from != null ? from : sheet.getToday();
231	        SettingValue v = settingValues.findById(new SettingValue.Key(id, key, on))
232	                .orElseGet(() -> new SettingValue(id, key, on, value));
233	        v.setValue(value);
234	        settingValues.saveAndFlush(v);
235	        if (PolicyVersion.KEYS.contains(key)) {
236	            policyVersions.saveAndFlush(
237	                    new PolicyVersion(id, policyVersions.countBySheetId(id) + 1, key, on, sheet.getToday(), shown));
238	        }
239	        history.record(id);
240	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value=" + shown
241	                + (from != null ? " from=" + from : ""));
242	        return sheet;
243	    }
