743	        Sheet sheet = load(id, user);
744	        if (parent != null) {
745	            if (parent.equals(id)) {
746	                throw new ResponseStatusException(HttpStatus.CONFLICT, "A sheet cannot be its own parent");
747	            }
748	            if (!sheets.existsById(parent)) {
