750	            }
751	            if (hasAncestor(parent, id)) {
752	                throw new ResponseStatusException(HttpStatus.CONFLICT, "The parent has this sheet as an ancestor");
753	            }
754	        }
755	        return rollup.tracking(id, user, () -> {
756	            sheet.setParentId(parent);
757	            Sheet saved = sheets.saveAndFlush(sheet);
758	            audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=parent value="
