778	    /** The ids of the other sheets of the sheet's tree, among the sheets that exist: its ancestors,
779	     *  however many levels up, and its descendants, however many levels down. */
780	    @Transactional(readOnly = true)
781	    public Set<String> tree(String id) {
782	        Set<String> tree = new HashSet<>();
783	        String at = sheets.findById(id).map(Sheet::getParentId).orElse(null);
784	        while (at != null && !at.equals(id) && tree.add(at)) {
785	            at = sheets.findById(at).map(Sheet::getParentId).orElse(null);
786	        }
787	        Set<String> below = new HashSet<>();
788	        Deque<String> next = new ArrayDeque<>(List.of(id));
789	        while (!next.isEmpty()) {
790	            for (Sheet child : sheets.findByParentId(next.pop())) {
791	                if (!child.getId().equals(id) && below.add(child.getId())) {
792	                    next.add(child.getId());
793	                }
794	            }
795	        }
796	        tree.addAll(below);
797	        tree.retainAll(sheets.findAllById(tree).stream().map(Sheet::getId).toList());
798	        return tree;
799	    }
