801	    /** Whether a sheet has another among its ancestors, however many levels up. */
802	    private boolean hasAncestor(String id, String ancestor) {
803	        Set<String> seen = new HashSet<>();
804	        String at = sheets.findById(id).map(Sheet::getParentId).orElse(null);
805	        while (at != null && seen.add(at)) {
806	            if (at.equals(ancestor)) {
807	                return true;
808	            }
809	            at = sheets.findById(at).map(Sheet::getParentId).orElse(null);
810	        }
811	        return false;
812	    }
