987	            "open", List.of("clerk", "steward"), "settle", List.of("clerk", "steward"),
988	            "void", List.of("clerk", "steward"), "close", List.of("clerk", "steward"),
989	            "reassign", List.of("steward"), "reopen", List.of("steward"),
990	            "today", List.of("clerk", "steward"));
991	
992	    /** The permission matrix as set on the sheet: for each action, the comma separated roles that may
993	     *  take it, blank ("") when it keeps the standing rule. */
994	    @Transactional(readOnly = true)
995	    public Map<String, String> permissions(String id) {
996	        Map<String, String> matrix = new TreeMap<>();
997	        for (String action : ACTIONS) {
998	            matrix.put(action, "");
999	        }
1000	        for (SheetPermission p : permissions.findBySheetId(id)) {
1001	            matrix.put(p.getAction(), p.getRoles());
1002	        }
1003	        return matrix;
1004	    }
1005	
1006	    /** The roles that may take an action on the sheet: those set in the matrix, or else the standing
1007	     *  rule's. */
1008	    @Transactional(readOnly = true)
1009	    public List<String> rolesAllowed(String id, String action) {
1010	        return permissions.findById(new SheetPermission.Key(id, action))
1011	                .map(p -> List.of(p.getRoles().split(",")))
1012	                .orElse(STANDING_PERMISSIONS.get(action));
1013	    }
1014	
1015	    /** Set the roles (a comma separated list; blank: the standing rule) that may take an action on the
1016	     *  sheet; recorded even when it is unchanged. */
1017	    @Transactional
1018	    public synchronized Sheet setPermission(String id, String user, String action, String roles) {
1019	        Sheet sheet = load(id, user);
1020	        if (roles.isEmpty()) {
1021	            permissions.deleteById(new SheetPermission.Key(id, action));
1022	        } else {
1023	            SheetPermission p = permissions.findById(new SheetPermission.Key(id, action))
1024	                    .orElseGet(() -> new SheetPermission(id, action, roles));
1025	            p.setRoles(roles);
1026	            permissions.saveAndFlush(p);
1027	        }
1028	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value=" + roles);
1029	        return sheet;
1030	    }
1031	}
