709	    for (const [id, ps] of this.patronShares()) {
710	      const shown = ps.flatMap((x) => {
711	        const p = people.get(x.id);
712	        return p === undefined ? [] : [{ name: p.name, shown: this.nameOf(p), share: x.share }];
713	      });
714	      shown.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
