733	  /** The claims that count toward claimed: a hold does not take a claim out of it. */
734	  private readonly claimedClaims = computed(() =>
735	    this.claims().filter((c) => !c.corrects && countsClaimed(c, this.byId().get(c.personId) ?? NO_LEAVE, this.session.today())));
736	  /** What each person has claimed: the sum of their open and settled claims' amounts, leaving out
737	   *  the deferred ones, the open ones of a retired person unbound by a statement, and the corrections. */
738	  protected readonly claimed = computed(() => {
