749	  private readonly caps = signal<DatedValue<string | null>[]>([]);
750	  /** The sheet's cap in force on a person's day: the date of their latest claim that counts, or
751	   *  else the sheet's today; the most their due-total comes to; null when there is no cap. */
752	  private capOf(p: Person): string | null {
753	    const today = this.session.today();
754	    const day = (this.claimsByPerson().get(p.id) ?? []).filter((c) => countsLive(c, p, today))
755	      .map((c) => c.date).reduce<string | null>((a, b) => (a === null || b > a ? b : a), null) ?? today;
756	    return day === null ? null : valueOn(this.caps(), day, null);
