784	  protected readonly roundings = signal<DatedValue<RoundingMode | null>[]>([]);
785	  /** The sheet's policy versions, the first made first: the current one is the last made. */
786	  protected readonly policyVersions = signal<PolicyVersion[]>([]);
787	  /** What the late charges of overdue claims, and the rounding of live figures, follow. */
788	  private readonly lateness = computed(() => ({
789	    today: this.session.today(), pcts: this.latePct(), graces: this.graces(), policyDate: this.policyDate(),
790	    roundings: this.roundings(),
791	  }));
792	  /** The periods on the sheet, earliest first. */
793	  protected readonly periods = signal<Period[]>([]);
794	  /** Each person's live due-total for each period, by the person's id then the period's id: the due
795	   *  figures of their claims whose due-by falls in it and that count by their status at its end,
796	   *  skipping those with no due. */
797	  private readonly livePeriodDues = computed(() => {
798	    const people = new Map(this.people().map((p) => [p.id, p]));
799	    const figures = new Map<number, Map<number, string[]>>();
800	    for (const c of this.claims()) {
801	      const period = periodOf(this.periods(), c.dueBy);
802	      const person = people.get(c.personId);
803	      if (period === undefined || person === undefined) continue;
804	      if (!countsAsOf(c, person, period.to, this.session.today())) continue;
805	      const d = claimDue(c, this.rates(), gradeOn(person.grades, c.date), this.floor(), this.lateness());
806	      if (d === null) continue;
807	      const theirs = figures.get(person.id) ?? new Map<number, string[]>();
808	      theirs.set(period.id, [...(theirs.get(period.id) ?? []), d]);
809	      figures.set(person.id, theirs);
810	    }
811	    const by = new Map<number, Map<number, string>>();
812	    for (const [id, theirs] of figures) by.set(id, new Map([...theirs].map(([pid, ds]) => [pid, sumAmounts(ds)])));
813	    return by;
814	  });
