689	     *  inBulk}) also takes a claim that is already the person's, listing it as their newest. */
690	    @Transactional
691	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId, boolean inBulk) {
692	        Claim claim = lock(sheetId, claimId);
693	        if (!roles.may(sheetId, user, "reassign")) {
694	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
695	        }
696	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
697	                || claim.getStatus() == ClaimStatus.DELETED) {
698	            throw new ResponseStatusException(HttpStatus.CONFLICT,
699	                    "A " + claim.getStatus() + " claim cannot be reassigned");
700	        }
701	        if (!inBulk && claim.getPersonId() == toPersonId) {
702	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
703	        }
