709	            // an unsettled claim has no number yet; one numbered before numbering moved to settlement keeps it
710	            claim.moveTo(to.getId(), claims.nextListed());
711	            Claim saved = claims.saveAndFlush(claim);
712	            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
713	                    + " from=" + from.getName() + " to=" + to.getName());
