727	        }
728	        Claim claim = lock(sheetId, claimId);
729	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
730	                || claim.getStatus() == ClaimStatus.DELETED) {
