858	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
859	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
860	     *  the same date and note, no number yet, opened by the user and due by the terms in force on
861	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
862	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
863	     *  allow the user's role to open a claim. */
864	    @Transactional
865	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
866	        Claim claim = lock(sheetId, claimId);
867	        refuseClosed(sheetId, claim.getDueBy());
868	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
869	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
870	        }
871	        if (!roles.may(sheetId, user, "open")) {
872	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
873	        }
874	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
875	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
876	                    "The amount split off must be above 0.00 and below the claim's amount");
877	        }
878	        return rollup.tracking(sheetId, user, () -> {
879	            Person person = person(sheetId, claim.getPersonId());
880	            int terms = terms(sheetId, person, sheets.today(sheetId));
881	            LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
882	            Claim draft = claim.splitOff(part, null, user, dueBy, terms);
883	            logStatus(sheetId, user, person, draft);
884	            Claim original = claims.saveAndFlush(claim);
885	            Claim split = claims.saveAndFlush(draft);
886	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + Objects.requireNonNullElse(split.getNumber(), ""));
887	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
888	            return new Split(original, split);
889	        });
890	    }
