960	    /** The number for a claim due by the day settled now: under period numbering, the next in its period
961	     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet
962	     *  within the fiscal year of its due-by day (<FY>-<n>). */
963	    public String nextNumber(String sheetId, LocalDate dueBy) {
964	        if (!sheets.periodNumbering(sheetId)) {
965	            return sheets.nextClaimNumber(sheetId, dueBy);
966	        }
967	        return periods.findOn(sheetId, dueBy)
968	                .map(p -> {
969	                    periods.advanceClaimNumber(p.getId());
970	                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
971	                })
972	                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
