975	    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
976	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
977	     *  or else it is refused; refused as well when it exceeds what remains of that claim: its amount
978	     *  less the corrections already made against it (VOID and DELETED ones, and the claim being
979	     *  edited, left out). */
980	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects, Long editing) {
981	        if (amount.signum() >= 0) {
982	            return null;
983	        }
984	        Claim corrected = (corrects == null ? Optional.<Claim>empty()
985	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
986	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
987	                        "A negative amount must correct a settled claim of the same person"));
988	        BigDecimal remains = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId).stream()
989	                .filter(c -> corrected.getNumber().equals(c.getCorrects()) && !c.getId().equals(editing)
990	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
991	                .map(Claim::getAmount).reduce(corrected.getAmount(), BigDecimal::add);
992	        if (amount.negate().compareTo(remains) > 0) {
993	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
994	                    "A correction may not exceed the " + remains + " that remains of claim " + corrects);
995	        }
996	        return corrected;
997	    }
