1016	     *  grade's when one is set, or else the sheet's); a claim with no due (n/a) is within any limit, and a steward settles
1017	     *  anything. */
1018	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
1019	        Person person = person(sheetId, claim.getPersonId());
1020	        BigDecimal limit = sheets.clerkLimitFor(sheetId, person.gradeOn(sheets.today(sheetId)), claim.getDate());
1021	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
