1029	     *  claim's date (its person's grade's on that date when one is set, or else the sheet's) when it
1030	     *  has no proofs, or, while the sheet has proof kinds, no proof of one of them; a claim with no
1031	     *  due (n/a) and a claim with no threshold need none. */
1032	    private void refuseUnproved(String sheetId, Claim claim) {
1033	        if (claim.getProofs() > 0
1034	                && sheets.proofKinds(sheetId).stream().allMatch(k -> claim.getProofsOf(k) > 0)) {
1035	            return;
1036	        }
1037	        Person person = person(sheetId, claim.getPersonId());
1038	        BigDecimal threshold = sheets.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
1039	        if (threshold == null) {
1040	            return;
1041	        }
1042	        BigDecimal due = dues.figure(sheetId, person, claim);
1043	        if (due != null && due.compareTo(threshold) > 0) {
1044	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
1045	                    "A claim whose due is above the proof threshold needs a proof of each kind the sheet lists first");
1046	        }
1047	    }
