1050	     *  already has that many open or pending claims. */
1051	    private void refuseOverMaxOpen(String sheetId, Claim claim) {
1052	        Integer max = sheets.maxOpen(sheetId);
1053	        if (max == null) {
1054	            return;
1055	        }
1056	        // one open at a time per person, so two opens at once cannot both slip under the maximum
1057	        people.lockByIdAndSheetId(claim.getPersonId(), sheetId);
1058	        if (claims.countOpen(sheetId, claim.getPersonId()) >= max) {
1059	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1060	                    "The person already has " + max + " open claims, the sheet's maximum");
