1065	     *  that many open or pending claims due inside it; the period stays locked until the transaction
1066	     *  ends, so two claims opened in it at once are counted one after the other. */
1067	    private void refuseOverCap(String sheetId, Claim claim) {
1068	        periods.findOn(sheetId, claim.getDueBy())
1069	                .filter(p -> p.getClaimCap() != null)
1070	                .flatMap(p -> periods.lockByIdAndSheetId(p.getId(), sheetId))
1071	                .ifPresent(p -> {
1072	                    if (claims.countOpenDueBetween(sheetId, claim.getPersonId(), p.getFromDate(), p.getToDate())
1073	                            >= p.getClaimCap()) {
1074	                        throw new ResponseStatusException(HttpStatus.CONFLICT,
1075	                                "The person already has " + p.getClaimCap() + " open claims in period " + p.getName());
