1081	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
1082	    private void refuseUnnoted(String sheetId, Claim claim) {
1083	        BigDecimal threshold = sheets.noteThreshold(sheetId, claim.getDate());
1084	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
1085	            return;
1086	        }
1087	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
1088	        if (due != null && due.compareTo(threshold) > 0) {
1089	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
1090	                    "A claim whose due is above the note threshold needs a note before it is opened");
1091	        }
