1094	    /** Whether a claim opened now goes to review: its due is above the sheet's review threshold in
1095	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold do not. */
1096	    private boolean overReviewThreshold(String sheetId, Claim claim) {
1097	        BigDecimal threshold = sheets.reviewThreshold(sheetId, claim.getDate());
1098	        if (threshold == null) {
1099	            return false;
1100	        }
1101	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
1102	        return due != null && due.compareTo(threshold) > 0;
1103	    }
