341	/** The shares of a person's patrons, in the order they were named: 100.00 split equally, each
342	 *  rounded half to even to two decimals, the remainder going to the first named. In hundredths. */
343	export function patronShares(count: number): number[] {
344	  if (count === 0) return [];
345	  const whole = Math.floor(10000 / count);
346	  const rest = 10000 - whole * count;
347	  const each = 2 * rest > count || (2 * rest === count && whole % 2 === 1) ? whole + 1 : whole;
348	  const shares = Array.from({ length: count }, () => each);
349	  shares[0] += 10000 - each * count;
350	  return shares;
351	}
