     1	import { HttpClient } from '@angular/common/http';
     2	import { Injectable, inject, signal } from '@angular/core';
     3	import { firstValueFrom } from 'rxjs';
     4	import { Grade } from './people';
     5	import { Session } from './session';
     6	
     7	// The dated settings (the clerk limit, the cap, the floor, the terms and the late percent) as in force
     8	// on the sheet's today.
     9	export interface Settings {
    10	  /** The most due a clerk may settle, as text with two decimals; null when there is no limit. */
    11	  clerkLimit: string | null;
    12	  /** The least live due a claim has, as text with two decimals. */
    13	  floor: string;
    14	  /** The days after its date a claim is due by. */
    15	  terms: number;
    16	  /** The percent of its figure an overdue claim gains for every full 30 days, as text with two decimals. */
    17	  latePct: string;
    18	  /** The policy date (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
    19	  policyDate: string | null;
    20	  /** The period numbering from date (yyyy-mm-dd); null when blank (off). */
    21	  periodNumberingFrom: string | null;
    22	  /** The terms each grade has of its own, by grade; a grade not in it takes the sheet's terms. */
    23	  gradeTerms: Partial<Record<Grade, number>>;
    24	  /** The most a person's due-total comes to, as text with two decimals; null when there is no cap. */
    25	  cap: string | null;
    26	  /** The floors recorded, each from its from-date, earliest first. */
    27	  floors: DatedValue[];
    28	  /** The late percents recorded, each from its from-date, earliest first. */
    29	  latePcts: DatedValue[];
    30	  /** The caps recorded (null: no cap), each from its from-date, earliest first. */
    31	  caps: DatedValue<string | null>[];
    32	  /** The due above which a claim needs a proof before it is settled or approved, as text with two
    33	   *  decimals; null when there is none. */
    34	  proofThreshold: string | null;
    35	  /** The due above which a claim cannot be opened with an empty note, as text with two decimals;
    36	   *  null when there is none. */
    37	  noteThreshold: string | null;
    38	  /** The due above which a claim goes to review when it is opened, as text with two decimals; null
    39	   *  when there is none. */
    40	  reviewThreshold: string | null;
    41	  /** The permission matrix: for each action, the comma separated roles that may take it; blank when
    42	   *  it keeps the standing rule. */
    43	  permissions: Record<PermAction, string>;
    44	  /** The grace days: when the sheet's today is changed, an open period whose to-date plus them is
    45	   *  before it is closed; null when blank (off). */
    46	  graceDays: number | null;
    47	  /** The escalation gap: reminding a claim this many days or more after its previous reminder
    48	   *  escalates it, once ever; null when blank (off). Not dated. */
    49	  escalateAfter: number | null;
    50	  /** The maximum of open claims per person: opening a claim is refused when its person already has
    51	   *  this many OPEN or PENDING claims; null when blank (none). Not dated. */
    52	  maxOpen: number | null;
    53	  /** The review SLA: a claim in review whose review day plus this many days is before the sheet's
    54	   *  today is late; null when blank (none). Not dated. */
    55	  reviewSla: number | null;
    56	  /** The pending SLA: a pending claim whose pending day plus this many days is before the sheet's
    57	   *  today is late; null when blank (none). Not dated. */
    58	  pendingSla: number | null;
    59	  /** The mid score threshold: while both thresholds are set, a person whose score is at or above
    60	   *  it is MID; null when blank. Not dated. */
    61	  scoreMid: number | null;
    62	  /** The high score threshold: while both thresholds are set, a person whose score is at or above
    63	   *  it is HIGH; null when blank. Not dated. */
    64	  scoreHigh: number | null;
    65	  /** The score log switch: while on, changing the sheet's today records each person's score on
    66	   *  the day being left. Not dated. */
    67	  scoreLog: boolean;
    68	  /** The entry date (yyyy-mm-dd): while it is set, a new claim's date when none is given; null when
    69	   *  blank (off, the sheet's today then stands in). */
    70	  entryDate: string | null;
    71	  /** The grace days each grade has in force on the sheet's today, by grade; a grade not in it has
    72	   *  none. */
    73	  gradeGraces: Partial<Record<Grade, number>>;
    74	  /** The grace days recorded for each grade (null: blank, none), each from its from-date, earliest
    75	   *  first. */
    76	  graces: Graces;
    77	  /** The proof threshold each grade has of its own in force on the sheet's today, as text with two
    78	   *  decimals, by grade; a grade not in it takes the sheet's. */
    79	  gradeProofThresholds: Partial<Record<Grade, string>>;
    80	  /** The clerk limit each grade has of its own in force on the sheet's today, as text with two
    81	   *  decimals, by grade; a grade not in it takes the sheet's. */
    82	  gradeClerkLimits: Partial<Record<Grade, string>>;
    83	  /** The pot a balanced pool's members cut by their shares, as text with two decimals; null when
    84	   *  blank (none). Not dated. */
    85	  pot: string | null;
    86	  /** The parent sheet's id: a grade with no rate in force on a date on this sheet takes the
    87	   *  parent's, then its parent's, up to three levels up; null when blank (none). Not dated. */
    88	  parent: string | null;
    89	  /** The proof kinds, comma separated: while set, a claim whose due is above the proof threshold
    90	   *  needs at least one proof of each before it is settled or approved; empty when blank (none).
    91	   *  Not dated. */
    92	  proofKinds: string;
    93	  /** The default grade: a person added by the quick-add bar, or by an import line with a blank
    94	   *  grade, is given it; null when blank (A). Not dated. */
    95	  defaultGrade: Grade | null;
    96	  /** The fiscal year start month, 1 to 12 (1 unless set): a fiscal year runs from the first day of
    97	   *  it. Not dated. */
    98	  fiscalStartMonth: number;
    99	  /** The alert threshold: a person whose due-total crosses above it is alerted, as text with two
   100	   *  decimals; null when blank (off). Not dated. */
   101	  alertThreshold: string | null;
   102	  /** The rounding mode in force on the sheet's today; null when blank (none: a claim rounds by the
   103	   *  policy date). */
   104	  rounding: RoundingMode | null;
   105	  /** The rounding modes recorded (null: blank, none), each from its from-date, earliest first. */
   106	  roundings: DatedValue<RoundingMode | null>[];
   107	  /** The number of the current policy version: how many have been made (0: none). */
   108	  policyVersion: number;
   109	  /** The policy versions, the first made first. */
   110	  policyVersions: PolicyVersion[];
   111	}
   112	
   113	/** A version of the sheet's policy, made by a change to one of its policy settings (the rounding
   114	 *  mode, the floor, the cap, the terms, the late percent, the clerk limit). */
   115	export interface PolicyVersion {
   116	  number: number;
   117	  /** The setting whose change made it. */
   118	  key: string;
   119	  /** yyyy-mm-dd; null when it has none (in force always). */
   120	  from: string | null;
   121	}
   122	
   123	/** A line of the policy viewer: a version with the value its setting was given (null when not kept)
   124	 *  and how many of the sheet's claims have it as their policy version. */
   125	export interface PolicyLine {
   126	  number: number;
   127	  /** yyyy-mm-dd; null when it has none (in force from the start). */
   128	  from: string | null;
   129	  key: string;
   130	  value: string | null;
   131	  claims: number;
   132	  /** The due of its claims that count, added up (two decimals). */
   133	  dueTotal: string;
   134	}
   135	
   136	/** The policy version in force on a day (yyyy-mm-dd): how many versions have no from-date or one
   137	 *  on or before it. */
   138	export function policyOn(versions: PolicyVersion[], day: string): number {
   139	  return versions.filter((v) => v.from === null || v.from <= day).length;
   140	}
   141	
   142	/** A rounding mode: how a claim's live figures round when one is in force on its date. */
   143	export type RoundingMode = 'half-up' | 'half-even';
   144	
   145	/** A rounding mode typed: half-up or half-even. */
   146	export const ROUNDING = /^(half-up|half-even)$/;
   147	
   148	/** The grace days recorded for each grade (null: blank, none), each from its from-date, earliest
   149	 *  first: a claim whose person's grade on its date has grace on that date is overdue only once its
   150	 *  due-by plus them is before the sheet's today. */
   151	export type Graces = Partial<Record<Grade, { from: string; value: number | null }[]>>;
   152	
   153	/** The grace days a grade has in force on a day (yyyy-mm-dd); 0 when none (blank, or never set). */
   154	export function graceOn(graces: Graces, grade: Grade | undefined, day: string): number {
   155	  if (grade === undefined) return 0;
   156	  let value: number | null = null;
   157	  for (const v of graces[grade] ?? []) {
   158	    if (v.from <= day) value = v.value;
   159	  }
   160	  return value ?? 0;
   161	}
   162	
   163	/** The actions the permission matrix covers. */
   164	export type PermAction = 'open' | 'settle' | 'void' | 'reassign' | 'close' | 'reopen' | 'today';
   165	
   166	export const PERM_ACTIONS: PermAction[] = ['open', 'settle', 'void', 'reassign', 'close', 'reopen', 'today'];
   167	
   168	/** The roles that may take each action when its entry in the matrix is blank. */
   169	export const STANDING_PERMISSIONS: Record<PermAction, string> = {
   170	  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', close: 'clerk,steward',
   171	  reassign: 'steward', reopen: 'steward', today: 'clerk,steward',
   172	};
   173	
   174	/** A proof kinds value: receipt, photo or both, comma separated. */
   175	export const PROOF_KIND_LIST = /^\s*(receipt|photo)\s*(,\s*(receipt|photo)\s*)*$/;
   176	
   177	/** A permission entry: a comma separated list of roles (clerk, steward). */
   178	export const PERM_ROLES = /^\s*(clerk|steward)\s*(,\s*(clerk|steward)\s*)*$/;
   179	
   180	/** A value a dated setting takes from a date on, as text with two decimals; null when blank. */
   181	export interface DatedValue<V extends string | null = string> {
   182	  /** yyyy-mm-dd */
   183	  from: string;
   184	  value: V;
   185	}
   186	
   187	/** The floor a sheet starts with, in force before every from-date of its own. */
   188	export const STARTING_FLOOR = '1.00';
   189	
   190	/** The late percent a sheet starts with, in force before every from-date of its own. */
   191	export const STARTING_LATE_PCT = '0.00';
   192	
   193	/** The value of a dated setting in force on a day (yyyy-mm-dd): the one with the latest from-date on
   194	 *  or before it, or else the starting value. */
   195	export function valueOn<V extends string | null>(recorded: DatedValue<V>[], day: string, starting: V): V {
   196	  let value = starting;
   197	  for (const v of recorded) {
   198	    if (v.from <= day) value = v.value;
   199	  }
   200	  return value;
   201	}
