   203	export type RoleName = 'clerk' | 'steward' | 'viewer' | 'restricted';
   204	
   205	export interface Role {
   206	  user: string;
   207	  role: RoleName;
   208	}
   209	
   210	/** The roles a user name can be given; a name given none is a clerk, a viewer may change nothing,
   211	 *  and a restricted user lists only the people of their crews and their own person. */
   212	export const ROLES: RoleName[] = ['clerk', 'steward', 'viewer', 'restricted'];
   213	
   214	/** A limit with up to two decimals, 0.00 or more. */
   215	export const LIMIT = /^\d{1,12}(\.\d{1,2})?$/;
   216	
   217	/** Terms: a whole number of days, 0 or more. */
   218	export const TERMS = /^\d{1,4}$/;
   219	
   220	/** A score threshold: a whole number, which may be below 0. */
   221	export const SCORE = /^-?\d{1,6}$/;
   222	
   223	/** A switch setting turned on: "on" (blank is off). */
   224	export const SWITCH_ON = /^on$/;
   225	
   226	/** A fiscal year start month: 1 to 12. */
   227	export const FISCAL_MONTH = /^(0?[1-9]|1[0-2])$/;
   228	
   229	/** A policy date: yyyy-mm-dd. */
   230	export const POLICY_DATE = /^\d{4}-\d{2}-\d{2}$/;
   231	
   232	/** A late percent with up to two decimals, 0.00 or more. */
   233	export const LATE_PCT = /^\d{1,5}(\.\d{1,2})?$/;
